  1→/**
  2→ * Backfill script: Index checkpoints into Turbopuffer for full-text + semantic search.
  3→ *
  4→ * Usage:
  5→ *   npx tsx scripts/backfill-search.ts [options]
  6→ *
  7→ * Options:
  8→ *   --repo <full_name>     Only backfill a specific repo (e.g., "entireio/cli")
  9→ *   --with-transcripts     Fetch transcript excerpts from GitHub (slower, needs GITHUB_TOKEN)
 10→ *   --dry-run              Show what would be indexed without writing to Turbopuffer
 11→ *   --limit <n>            Max checkpoints per repo (for testing)
 12→ *
 13→ * Environment:
 14→ *   DATABASE_URL           MySQL connection string (defaults to local Docker MySQL)
 15→ *   TURBOPUFFER_API_KEY    Turbopuffer API key (required unless --dry-run)
 16→ *   OPENAI_API_KEY         OpenAI API key for embeddings (required unless --dry-run)
 17→ *   GITHUB_TOKEN           GitHub PAT with repo read access (required for --with-transcripts)
 18→ */
 19→
 20→import { Kysely, MysqlDialect } from "kysely";
 21→import { createPool } from "mysql2";
 22→import type { DB } from "../db/types";
 23→import { Turbopuffer } from "@turbopuffer/turbopuffer";
 24→import type { Vector } from "@turbopuffer/turbopuffer";
 25→import OpenAI from "openai";
 26→import { getParserForAgent } from "../src/lib/transcript-parsers/registry";
 27→
 28→// --- Config ---
 29→
 30→const EMBEDDING_MODEL = "text-embedding-3-small";
 31→const EMBEDDING_DIMENSIONS = 1536;
 32→const CHUNK_SIZE = 50; // process checkpoints in chunks of 50 (fetch transcripts + embed + upsert per chunk)
 33→const CHECKPOINT_BRANCH = "entire/checkpoints/v1";
 34→const GITHUB_API = "https://api.github.com";
 35→const TRANSCRIPT_DELAY_MS = 100; // delay between GitHub API calls to avoid rate limiting
 36→const MAX_TRANSCRIPT_CHARS = 2000;
 37→const MAX_ATTRIBUTE_BYTES = 3800; // Turbopuffer limit is 4096, leave headroom
 38→const MAX_EMBEDDING_CHARS = 25000; // ~8K tokens, text-embedding-3-small limit is 8192 tokens
 39→const MAX_RETRIES = 3;
 40→const RETRY_BASE_DELAY_MS = 1000;
 41→
 42→// --- CLI Argument Parsing ---
 43→
 44→interface CliOptions {
 45→  repo: string | null;
 46→  withTranscripts: boolean;
 47→  dryRun: boolean;
 48→  limit: number | null;
 49→}
 50→
 51→function parseArgs(): CliOptions {
 52→  const args = process.argv.slice(2);
 53→  const options: CliOptions = {
 54→    repo: null,
 55→    withTranscripts: false,
 56→    dryRun: false,
 57→    limit: null,
 58→  };
 59→
 60→  for (let i = 0; i < args.length; i++) {
 61→    switch (args[i]) {
 62→      case "--repo":
 63→        options.repo = args[++i];
 64→        if (!options.repo) {
 65→          console.error("Error: --repo requires a value (e.g., 'entireio/cli')");
 66→          process.exit(1);
 67→        }
 68→        break;
 69→      case "--with-transcripts":
 70→        options.withTranscripts = true;
 71→        break;
 72→      case "--dry-run":
 73→        options.dryRun = true;
 74→        break;
 75→      case "--limit":
 76→        options.limit = parseInt(args[++i], 10);
 77→        if (isNaN(options.limit) || options.limit <= 0) {
 78→          console.error("Error: --limit requires a positive integer");
 79→          process.exit(1);
 80→        }
 81→        break;
 82→      default:
 83→        console.error(`Unknown option: ${args[i]}`);
 84→        console.error("Usage: npx tsx scripts/backfill-search.ts [--repo <name>] [--with-transcripts] [--dry-run] [--limit <n>]");
 85→        process.exit(1);
 86→    }
 87→  }
 88→
 89→  return options;
 90→}
 91→
 92→// --- Database Setup ---
 93→
 94→function createDb(): Kysely<DB> {
 95→  const url = process.env.DATABASE_URL ?? "mysql://entire:entire@localhost:3306/entire";
 96→  const parsed = new URL(url);
 97→  const isLocalhost = parsed.hostname === "localhost" || parsed.hostname === "127.0.0.1";
 98→
 99→  return new Kysely<DB>({
100→    dialect: new MysqlDialect({
101→      pool: createPool({
102→        host: parsed.hostname,
103→        port: Number(parsed.port) || 3306,
104→        user: decodeURIComponent(parsed.username),
105→        password: decodeURIComponent(parsed.password),
106→        database: parsed.pathname.replace("/", ""),
107→        ssl: isLocalhost ? undefined : { rejectUnauthorized: true },
108→      }),
109→    }),
110→  });
111→}
112→
113→// --- Text Construction ---
114→
115→function buildSearchText(
116→  checkpoint: CheckpointRow,
117→  transcriptExcerpt?: string,
118→): string {
119→  const parts: string[] = [];
120→
121→  if (checkpoint.prompt) {
122→    parts.push(`Prompt: ${checkpoint.prompt}`);
123→  }
124→  if (checkpoint.commit_message) {
125→    parts.push(`Commit: ${checkpoint.commit_message}`);
126→  }
127→  if (checkpoint.files_touched_str) {
128→    parts.push(`Files: ${checkpoint.files_touched_str}`);
129→  }
130→  if (transcriptExcerpt) {
131→    parts.push(`Transcript: ${transcriptExcerpt}`);
132→  }
133→
134→  return parts.join("\n");
135→}
136→
137→// --- Embedding Generation ---
138→
139→async function generateEmbeddings(
140→  openai: OpenAI,
141→  texts: string[],
142→): Promise<number[][]> {
143→  const response = await openai.embeddings.create({
144→    model: EMBEDDING_MODEL,
145→    input: texts,
146→    dimensions: EMBEDDING_DIMENSIONS,
147→  });
148→
149→  // Sort by index to maintain order
150→  return response.data
151→    .sort((a, b) => a.index - b.index)
152→    .map((item) => item.embedding);
153→}
154→
155→// --- Attribute Truncation ---
156→
157→function truncateToBytes(str: string | null, maxBytes: number): string | null {
158→  if (str === null) return null;
159→  // Fast path: ASCII strings where 1 char = 1 byte
160→  if (str.length <= maxBytes) return str;
161→  // Truncate by encoding to bytes
162→  const encoder = new TextEncoder();
163→  const encoded = encoder.encode(str);
164→  if (encoded.length <= maxBytes) return str;
165→  // Find the last valid UTF-8 boundary within maxBytes
166→  const truncated = encoded.slice(0, maxBytes);
167→  const decoder = new TextDecoder("utf-8", { fatal: false });
168→  return decoder.decode(truncated);
169→}
170→
171→// --- Fetch with Retry ---
172→
173→async function fetchWithRetry(
174→  url: string,
175→  options: RequestInit,
176→): Promise<Response> {
177→  for (let attempt = 0; attempt < MAX_RETRIES; attempt++) {
178→    try {
179→      const response = await fetch(url, options);
180→      // Retry on transient server errors and rate limits
181→      if (response.status >= 500 || response.status === 429) {
182→        if (attempt < MAX_RETRIES - 1) {
183→          const delay = RETRY_BASE_DELAY_MS * Math.pow(2, attempt);
184→          await sleep(delay);
185→          continue;
186→        }
187→      }
188→      return response;
189→    } catch (err) {
190→      if (attempt < MAX_RETRIES - 1) {
191→        const delay = RETRY_BASE_DELAY_MS * Math.pow(2, attempt);
192→        await sleep(delay);
193→        continue;
194→      }
195→      throw err;
196→    }
197→  }
198→  throw new Error("fetchWithRetry: exhausted retries");
199→}
200→
201→// --- Transcript Fetching ---
202→
203→async function fetchTranscriptExcerpt(
204→  repoFullName: string,
205→  checkpointId: string,
206→  agent: string,
207→  token: string,
208→): Promise<string | null> {
209→  const folder = `${checkpointId.slice(0, 2)}/${checkpointId.slice(2)}`;
210→  const path = `${folder}/0/full.jsonl`;
211→
212→  // Encode each path segment individually (preserves / separators)
213→  const encodedPath = path.split("/").map(encodeURIComponent).join("/");
214→  const url = `${GITHUB_API}/repos/${repoFullName}/contents/${encodedPath}?ref=${CHECKPOINT_BRANCH}`;
215→
216→  try {
217→    const response = await fetchWithRetry(url, {
218→      headers: {
219→        Accept: "application/vnd.github.raw+json",
220→        Authorization: `Bearer ${token}`,
221→        "User-Agent": "entire-backfill",
222→        "X-GitHub-Api-Version": "2022-11-28",
223→      },
224→    });
225→
226→    if (!response.ok) {
227→      if (response.status === 404) {
228→        return null;
229→      }
230→      return null;
231→    }
232→
233→    const content = await response.text();
234→
235→    const parser = getParserForAgent(agent);
236→    const result = parser.parse(content);
237→
238→    if (result.messages.length === 0) {
239→      return null;
240→    }
241→
242→    // Extract first user message + first assistant message
243→    const parts: string[] = [];
244→    let charsUsed = 0;
245→
246→    for (const msg of result.messages) {
247→      if (charsUsed >= MAX_TRANSCRIPT_CHARS) break;
248→
249→      const remaining = MAX_TRANSCRIPT_CHARS - charsUsed;
250→      const text = msg.content.slice(0, remaining);
251→      parts.push(`[${msg.role}]: ${text}`);
252→      charsUsed += text.length;
253→
254→      // Only take the first user + first assistant
255→      if (msg.role === "assistant") break;
256→    }
257→
258→    return parts.join("\n") || null;
259→  } catch {
260→    return null;
261→  }
262→}
263→
264→function sleep(ms: number): Promise<void> {
265→  return new Promise((resolve) => setTimeout(resolve, ms));
266→}
267→
268→// --- Types ---
269→
270→interface CheckpointRow {
271→  checkpoint_id: string;
272→  branch: string;
273→  agent: string;
274→  commit_author_username: string | null;
275→  created_at: string | null;
276→  commit_sha: string | null;
277→  commit_message: string | null;
278→  prompt: string | null;
279→  files_touched_str: string | null;
280→}
281→
282→interface RepoRow {
283→  id: string;
284→  full_name: string;
285→  checkpoint_count: number;
286→}
287→
288→// --- Per-Repo Processing ---
289→
290→async function fetchCheckpointsForRepo(
291→  db: Kysely<DB>,
292→  repoId: string,
293→  limit: number | null,
294→): Promise<CheckpointRow[]> {
295→  // Use the same deferred-join pattern as getCheckpointsForBranch
296→  let idQuery = db
297→    .selectFrom("repo_checkpoint_commits")
298→    .select("id")
299→    .where("repo_id", "=", repoId)
300→    .orderBy("commit_date", "desc");
301→
302→  if (limit) {
303→    idQuery = idQuery.limit(limit);
304→  }
305→
306→  const idRows = await idQuery.execute();
307→  if (idRows.length === 0) return [];
308→
309→  const rows = await db
310→    .selectFrom("repo_checkpoint_commits as cc")
311→    .leftJoin("repo_checkpoints as cp", (join) =>
312→      join
313→        .onRef("cp.repo_id", "=", "cc.repo_id")
314→        .onRef("cp.checkpoint_id", "=", "cc.checkpoint_id"),
315→    )
316→    .select([
317→      "cc.checkpoint_id",
318→      "cc.branch",
319→      "cc.commit_sha",
320→      "cc.commit_message",
321→      "cc.commit_author_username",
322→      "cc.commit_date",
323→      "cp.prompt",
324→      "cp.agent",
325→      "cp.created_at",
326→      "cp.files_touched",
327→    ])
328→    .where(
329→      "cc.id",
330→      "in",
331→      idRows.map((r) => r.id),
332→    )
333→    .execute();
334→
335→  return rows.map((row) => {
336→    const filesTouched = row.files_touched as string[] | null;
337→    return {
338→      checkpoint_id: row.checkpoint_id,
339→      branch: row.branch,
340→      agent: row.agent ?? "Claude Code",
341→      commit_author_username: row.commit_author_username,
342→      created_at: row.created_at?.toISOString() ?? row.commit_date?.toISOString() ?? null,
343→      commit_sha: row.commit_sha,
344→      commit_message: row.commit_message,
345→      prompt: row.prompt,
346→      files_touched_str: filesTouched?.join(", ") ?? null,
347→    };
348→  });
349→}
350→
351→function formatElapsed(ms: number): string {
352→  const s = Math.floor(ms / 1000);
353→  if (s < 60) return `${s}s`;
354→  const m = Math.floor(s / 60);
355→  return `${m}m${s % 60}s`;
356→}
357→
358→async function processRepo(
359→  db: Kysely<DB>,
360→  tpuf: Turbopuffer,
361→  openai: OpenAI,
362→  repo: RepoRow,
363→  options: CliOptions,
364→): Promise<{ indexed: number; skipped: number }> {
365→  const start = Date.now();
366→  const total = repo.checkpoint_count;
367→  console.log(`\n--- ${repo.full_name} (${total} checkpoints) ---`);
368→
369→  const checkpoints = await fetchCheckpointsForRepo(db, repo.id, options.limit);
370→  if (checkpoints.length === 0) {
371→    console.log(`  No checkpoint commits found, skipping.`);
372→    return { indexed: 0, skipped: 0 };
373→  }
374→
375→  console.log(`  Fetched ${checkpoints.length} checkpoint rows from DB.`);
