function getApiBaseUrl(): string {
  if (import.meta.env.VITE_API_BASE_URL) {
    return import.meta.env.VITE_API_BASE_URL;
  }
  // In development, use the same hostname as the current page to support local network access
  if (import.meta.env.DEV && typeof window !== "undefined") {
    return `http://${window.location.hostname}:8787`;
  }
  return "https://entire.io";
}

const API_BASE_URL = getApiBaseUrl();

type RequestOptions = RequestInit & { token?: string };

export class ApiError extends Error {
  status: number;
  constructor(message: string, status: number) {
    super(message);
    this.name = "ApiError";
    this.status = status;
  }
}

// Read a cookie value by name
export function getCookie(name: string): string | null {
  const match = document.cookie.match(new RegExp(`(^|; )${name}=([^;]*)`));
  return match ? match[2] : null;
}

/**
 * Check if an error indicates the user needs to re-authenticate with GitHub.
 * Used to show appropriate UI when GitHub OAuth tokens have expired.
 *
 * Matches specific API error messages that indicate auth issues:
 * - "Not authenticated" (401) - no session
 * - "Session expired" (401) - session timed out
 * - "GitHub token required for this operation" (403) - token missing/invalid
 * - "GitHub token expired" (401) - GitHub rejected the token (e.g. after concurrent refresh)
 */
export function isAuthError(error: Error | null | undefined): boolean {
  if (!error) return false;
  const message = error.message.toLowerCase();
  return (
    message === "not authenticated" ||
    message === "session expired" ||
    message === "github token required for this operation" ||
    message === "github token expired"
  );
}

export function normalizeErrorMessage(data: unknown, fallback: string): string {
  if (data && typeof data === "object") {
    if (
      "error" in data &&
      typeof (data as { error?: unknown }).error === "string"
    ) {
      return (data as { error: string }).error;
    }

    if (
      "errors" in data &&
      Array.isArray((data as { errors?: unknown }).errors)
    ) {
      const errors = (data as { errors: unknown[] }).errors.filter(
        (message): message is string => typeof message === "string",
      );

      if (errors.length > 0) {
        return errors.join(", ");
      }
    }
  }

  return fallback;
}

export async function request<T>(
  endpoint: string,
  options: RequestOptions = {},
): Promise<T> {
  const { token: _token, headers, ...rest } = options;
  const requestHeaders = new Headers(headers ?? {});

  if (rest.body && !requestHeaders.has("Content-Type")) {
    requestHeaders.set("Content-Type", "application/json");
  }

  // Add CSRF token header for state-changing requests (double-submit cookie pattern)
  const method = (rest.method ?? "GET").toUpperCase();
  if (["POST", "PUT", "DELETE", "PATCH"].includes(method)) {
    const csrfToken = getCookie("csrf");
    if (csrfToken) {
      requestHeaders.set("X-CSRF-Token", csrfToken);
    }
  }

  const response = await fetch(`${API_BASE_URL}${endpoint}`, {
    ...rest,
    headers: requestHeaders,
    credentials: "include",
  });

  let data: unknown = null;
  const contentType = response.headers.get("Content-Type") ?? "";

  if (contentType.includes("application/json")) {
    data = await response.json().catch(() => null);
  }

  if (!response.ok) {
    const message = normalizeErrorMessage(
      data,
      response.statusText || "Request failed",
    );
    throw new ApiError(message, response.status);
  }

  return data as T;
}

