/** Map a DB checkpoint row to the API CheckpointInfo shape */
function mapCheckpointToInfo(row: CheckpointWithCommit): CheckpointInfo {
  return {
    commitSha: row.commit_sha,
    commitMessage: row.commit_message,
    commitAuthor: row.commit_author,
    commitAuthorUsername: row.commit_author_username,
    commitDate: row.commit_date,
    additions: row.additions,
    deletions: row.deletions,
    filesChanged: row.files_changed,
    filesTouched: row.files_touched,
    fileStats: row.file_stats,
    checkpointId: row.checkpoint_id,
    createdAt: row.created_at ?? new Date().toISOString(),
    sessions: [
      {
        prompt: row.prompt,
        agent: row.agent ?? "Claude Code",
        steps: row.steps ?? 1,
      },
    ],
    sessionCount: row.session_count ?? 1,
    totalSteps: row.steps ?? 1,
    agents: [row.agent ?? "Claude Code"],
    inputTokens: row.input_tokens,
    cacheCreationTokens: row.cache_creation_tokens,
    cacheReadTokens: row.cache_read_tokens,
    outputTokens: row.output_tokens,
    apiCallCount: row.api_call_count,
    attribution:
      row.attribution_calculated_at != null
        ? {
          calculatedAt: row.attribution_calculated_at,
          agentLines: row.attribution_agent_lines ?? 0,
          humanAdded: row.attribution_human_added ?? 0,
          humanModified: row.attribution_human_modified ?? 0,
          humanRemoved: row.attribution_human_removed ?? 0,
          totalCommitted: row.attribution_total_committed ?? 0,
          agentPercentage: row.attribution_agent_percentage ?? 0,
        }
        : null,
  };
}

export const cacheRoutes = new Hono<{ Bindings: Env; Variables: Variables }>();

// User-specific routes — require authentication (applied per-route to avoid
// Hono middleware bleeding when both sub-routers are mounted at the same path)
const userRoutes = new Hono<{ Bindings: Env; Variables: Variables }>();

// Repo-specific routes — auth optional (public repos accessible without login)
// Middleware applied per-route for the same reason as above.
