// Get branches for a specific repo
repoRoutes.get("/:org/:repo/branches", optionalAuth, rateLimitUnauthenticated, async (c) => {
  const userId = c.get("userId") as string | undefined;

  const org = c.req.param("org");
  const repo = c.req.param("repo");
  const repoFullName = `${org}/${repo}`;

  const cacheKey = `branches:${repoFullName}`;

  const db = getDb(c.env);

  // Check repo access BEFORE cache lookup (cache is shared across users)
  const repoAccess = await checkRepoAccess(db, repoFullName, userId);
  if (repoAccess instanceof Response) return repoAccess;
  if (!repoAccess) return c.json({ error: "Repository not found" }, 404);

  // Get default_branch from repo record (falls back to "main" if not in DB)
  const defaultBranch = repoAccess.default_branch ?? "main";

  // Try cache first
  const cached = await c.env.ENTIRE_CACHE.get<{ branches: string[]; default_branch: string; stored_default_branch?: string }>(
    cacheKey,
    "json",
  );

  if (cached) {
    // Prefer the cached default_branch (may have been self-healed) over the DB value,
    // since the DB update from self-healing may not have completed yet
    return c.json({
      ...cached,
      default_branch: cached.default_branch ?? defaultBranch,
      stored_default_branch: cached.stored_default_branch ?? defaultBranch,
      from_cache: true,
    });
  }

  try {
    // Get a token: user's OAuth token if authenticated, installation token otherwise.
    // Token may be undefined for public repos without an installation — GitHub's
    // public API still works (rate-limited to 60 req/hr per IP).
    const tokenResult = await getGitHubTokenForRepoRequest(c, db, userId, repoAccess);
    if (tokenResult.response) return tokenResult.response;
    const token = tokenResult.token ?? undefined;

    const { fetchRepoBranches, fetchRepoDefaultBranch } = await import("../lib/github");
    const branches = await fetchRepoBranches(repoFullName, token);

    // Self-heal: if DB's default_branch isn't in the actual branch list,
    // fetch the real default from GitHub and update the DB
    let resolvedDefaultBranch = defaultBranch;
    if (!branches.includes(defaultBranch)) {
      console.log(`[branches] default_branch mismatch for ${repoFullName}: DB has "${defaultBranch}" but it's not in branch list`);
      const githubDefault = token ? await fetchRepoDefaultBranch(repoFullName, token) : null;
      if (githubDefault && branches.includes(githubDefault)) {
        console.log(`[branches] Healing default_branch for ${repoFullName}: "${defaultBranch}" -> "${githubDefault}"`);
        resolvedDefaultBranch = githubDefault;
        // Persist corrected default_branch in background via waitUntil
        const identifier = repoAccess ? { id: repoAccess.id } : { fullName: repoFullName };
        await runInBackground(c, () =>
          db.repos.updateDefaultBranch(identifier, githubDefault)
        );
      }
    }

    const data = {
      branches,
      default_branch: resolvedDefaultBranch,
      // Raw DB value before self-healing — the repos list navigates to this,
      // so the frontend needs it to detect stale-default redirects
      stored_default_branch: defaultBranch,
    };

    await c.env.ENTIRE_CACHE.put(cacheKey, JSON.stringify(data), {
      expirationTtl: 60 * 60, // 1 hour TTL
    });

    return c.json({ ...data, from_cache: false });
  } catch (err) {
    if (isGitHubAuthError(err)) {
      return c.json({ error: "GitHub token expired" }, 401);
    }
    console.error(`Failed to fetch branches for ${repoFullName}:`, err);
    recordSpanError(err);
    return c.json({ error: "Failed to fetch branches" }, 500);
  }
});

