/** Middleware: require authenticated admin user for trail routes */
async function requireTrailsAdmin(
  c: Context<{ Bindings: Env; Variables: Variables }>,
  next: () => Promise<void>,
): Promise<Response | void> {
  const userId = c.get("userId");
  const db = getDb(c.env);
  const user = await db.users.findById(userId);
  if (!user || !isAdmin(c.env, user.is_admin ?? false)) {
    return c.json({ error: "Forbidden" }, 403);
  }
  await next();
}

// Get all trails for a specific repo
repoRoutes.get("/:org/:repo/trails", requireAuth, requireTrailsAdmin, async (c) => {
  const userId = c.get("userId");

  const org = c.req.param("org");
  const repo = c.req.param("repo");
  const repoFullName = `${org}/${repo}`;

  try {
    const db = getDb(c.env);

    // Check repo access
    const repoAccess = await checkRepoAccess(db, repoFullName, userId, { requireRepo: true });
    if (repoAccess instanceof Response) return repoAccess;

    const user = await db.users.findById(userId);
    if (!user) {
      return c.json({ error: "User not found" }, 404);
    }

    let token: string | undefined;
    if (user.github_token_enc) {
      const result = await getValidGitHubTokenFromContext(c, db, user);
      token = result.token;
    }

    if (!token) {
      return c.json({ error: "GitHub token required" }, 401);
    }

    // Check if trails branch exists
    const branchExists = await checkBranchExists(repoFullName, TRAILS_BRANCH, token);
    if (!branchExists) {
      return c.json({
        trails: [],
        repo_full_name: repoFullName,
        updated_at: new Date().toISOString(),
      });
    }

    // Discover and fetch trails
    const trailIds = await discoverTrailsFromBranch(repoFullName, token);
    const trailData = await fetchTrailDataBatch(repoFullName, trailIds, token);

    // Get checkpoint counts per branch for each trail
    const trails: TrailInfo[] = [];
    for (const [trailId, trail] of trailData) {
      const { metadata, discussion } = trail;

      // Calculate comment counts
      let commentCount = 0;
      let unresolvedCount = 0;
      for (const comment of discussion.comments ?? []) {
        commentCount += 1 + (comment.replies?.length ?? 0);
        if (!comment.resolved) {
          unresolvedCount++;
        }
      }

      // Get checkpoint count for this branch from DB
      let checkpointCount = 0;
      try {
        checkpointCount = await db.checkpoints.countForBranch(repoAccess.id, metadata.branch);
      } catch {
        // Ignore errors - just use 0
      }

      trails.push({
        trail_id: trailId,
        branch: metadata.branch,
        base: metadata.base,
        title: metadata.title,
        body: metadata.body ?? "",
        status: metadata.status,
        author: metadata.author,
        assignees: metadata.assignees,
        labels: metadata.labels,
        created_at: metadata.created_at,
        updated_at: metadata.updated_at,
        merged_at: metadata.merged_at,
        priority: metadata.priority ?? "none",
        type: metadata.type ?? null,
        reviewers: metadata.reviewers ?? [],
        comment_count: commentCount,
        unresolved_count: unresolvedCount,
        checkpoint_count: checkpointCount,
      });
    }

    return c.json({
      trails,
      repo_full_name: repoFullName,
      updated_at: new Date().toISOString(),
    });
  } catch (err) {
    if (isGitHubAuthError(err)) {
      return c.json({ error: "GitHub token expired" }, 401);
    }
    console.error(`Failed to fetch trails for ${repoFullName}:`, err);
    recordSpanError(err);
    return c.json({ error: "Failed to fetch trails" }, 500);
  }
});

// Create a new trail
repoRoutes.post("/:org/:repo/trails", requireAuth, requireTrailsAdmin, async (c) => {
  const userId = c.get("userId");

  const org = c.req.param("org");
  const repo = c.req.param("repo");
  const repoFullName = `${org}/${repo}`;

  try {
    const db = getDb(c.env);

    // Check repo access
    const repoAccess = await checkRepoAccess(db, repoFullName, userId, { requireRepo: true });
    if (repoAccess instanceof Response) return repoAccess;

    const user = await db.users.findById(userId);
    if (!user) {
      return c.json({ error: "User not found" }, 404);
    }

    // Use installation token for write operations (has Contents: write permission)
    if (!repoAccess.installation_id) {
      return c.json({ error: "Repository has no app installation" }, 400);
    }

    const githubInstallationId = await db.installations.getGithubId(repoAccess.installation_id);
    if (!githubInstallationId) {
      return c.json({ error: "Installation not found" }, 400);
    }

    const token = await getInstallationToken(
      githubInstallationId,
      {
        appId: c.env.GITHUB_CLIENT_ID,
        privateKey: c.env.GITHUB_APP_PRIVATE_KEY,
      },
      c.env.ENTIRE_CACHE
    );

    // Parse request body
    const body = await c.req.json<{
      title: string;
      body?: string;
      branch_name: string;
      base?: string;
      assignees?: string[];
      labels?: string[];
      priority?: TrailPriority;
      type?: TrailType;
    }>();

    // Validate required fields
    if (!body.title?.trim()) {
      return c.json({ error: "Title is required" }, 400);
    }
    if (!body.branch_name?.trim()) {
      return c.json({ error: "Branch name is required" }, 400);
    }

    // Validate branch name format
    if (!isValidBranchName(body.branch_name)) {
      return c.json({ error: "Invalid branch name format" }, 400);
    }

    // Prevent creating branches in the reserved 'entire/' namespace
    if (body.branch_name.startsWith("entire/")) {
      return c.json({ error: "Cannot create branches under 'entire/' namespace" }, 400);
    }

    // Validate priority and type
    if (body.priority !== undefined && !VALID_PRIORITIES.includes(body.priority)) {
      return c.json({ error: `Invalid priority. Must be one of: ${VALID_PRIORITIES.join(", ")}` }, 400);
    }
    if (body.type !== undefined && !VALID_TYPES.includes(body.type)) {
      return c.json({ error: `Invalid type. Must be one of: ${VALID_TYPES.join(", ")}` }, 400);
    }

    const base = body.base || repoAccess.default_branch || "main";
    const trailId = generateTrailId();
    const now = new Date().toISOString();

    // Create the feature branch (if it doesn't exist)
    const branchCreated = await createBranchIfNotExists(
      repoFullName,
      body.branch_name,
      base,
      token
    );

    // Create trail metadata
    const metadata: TrailMetadata = {
      trail_id: trailId,
      branch: body.branch_name,
      base: base,
      title: body.title.trim(),
      body: body.body?.trim() || "",
      status: "draft",
      author: user.github_login || "unknown",
      assignees: body.assignees || [],
      labels: body.labels || [],
      created_at: now,
      updated_at: now,
      merged_at: null,
      priority: body.priority ?? "none",
      type: body.type,
      reviewers: [],
    };

    const discussion: TrailDiscussion = {
      comments: [],
    };

    const checkpoints: TrailCheckpoints = {
      checkpoints: [],
    };

    // Commit to entire/trails/v1 branch
    await commitTrailFiles(
      repoFullName,
      trailId,
      metadata,
      discussion,
      checkpoints,
      token,
      `Create trail: ${body.title.trim()}`
    );

    const trailInfo: TrailInfo = {
      ...metadata,
      priority: metadata.priority ?? "none",
      type: metadata.type ?? null,
      reviewers: metadata.reviewers ?? [],
      comment_count: 0,
      unresolved_count: 0,
      checkpoint_count: 0,
    };

    return c.json({
      trail: trailInfo,
      branch_created: branchCreated,
    }, 201);
  } catch (err) {
    if (isGitHubAuthError(err)) {
      return c.json({ error: "GitHub token expired" }, 401);
    }
    console.error(`Failed to create trail for ${repoFullName}:`, err);
    recordSpanError(err);
    return c.json({ error: "Failed to create trail" }, 500);
  }
});

// Get a single trail by ID
repoRoutes.get("/:org/:repo/trails/:trailId", requireAuth, requireTrailsAdmin, async (c) => {
  const userId = c.get("userId");

  const org = c.req.param("org");
  const repo = c.req.param("repo");
  const trailId = c.req.param("trailId");
  const repoFullName = `${org}/${repo}`;

  // Validate trail ID format
  if (!isValidTrailId(trailId)) {
    return c.json({ error: "Invalid trail ID format" }, 400);
  }

  try {
    const db = getDb(c.env);

    // Check repo access
    const repoAccess = await checkRepoAccess(db, repoFullName, userId, { requireRepo: true });
    if (repoAccess instanceof Response) return repoAccess;

    const user = await db.users.findById(userId);
    if (!user) {
      return c.json({ error: "User not found" }, 404);
    }

    let token: string | undefined;
    if (user.github_token_enc) {
      const result = await getValidGitHubTokenFromContext(c, db, user);
      token = result.token;
    }

    if (!token) {
      return c.json({ error: "GitHub token required" }, 401);
    }

    // Fetch the specific trail
    const trailData = await fetchTrailDataBatch(repoFullName, [trailId], token);
    const trail = trailData.get(trailId);

    if (!trail) {
      return c.json({ error: "Trail not found" }, 404);
    }

    const { metadata, discussion, checkpoints: trailCheckpoints } = trail;

    // Calculate comment counts
    let commentCount = 0;
    let unresolvedCount = 0;
    for (const comment of discussion.comments ?? []) {
      commentCount += 1 + (comment.replies?.length ?? 0);
      if (!comment.resolved) {
        unresolvedCount++;
      }
    }

    // Fetch checkpoints: use explicit IDs from checkpoints.json if available,
    // otherwise fall back to branch-based lookup (same as checkpoints page)
    const checkpointIds = trailCheckpoints.checkpoints.map((cp) => cp.checkpoint_id);
    let enrichedCheckpoints: CheckpointInfo[] = [];
    try {
      let dbCheckpoints;
      if (checkpointIds.length > 0) {
        try {
          dbCheckpoints = await db.checkpoints.getByIds(repoAccess.id, checkpointIds);
        } catch {
          // getByIds not implemented (e.g. Supabase) — fall back to branch query
          dbCheckpoints = await db.checkpoints.getForBranch(repoAccess.id, metadata.branch);
        }
      } else {
        dbCheckpoints = await db.checkpoints.getForBranch(repoAccess.id, metadata.branch);
      }
      enrichedCheckpoints = dbCheckpoints.map(mapCheckpointToInfo);
    } catch {
      // Ignore errors - return empty checkpoints
    }

    const trailInfo: TrailInfo = {
      ...metadata,
      body: metadata.body ?? "",
      priority: metadata.priority ?? "none",
      type: metadata.type ?? null,
      reviewers: metadata.reviewers ?? [],
      comment_count: commentCount,
      unresolved_count: unresolvedCount,
      checkpoint_count: enrichedCheckpoints.length,
    };

    return c.json({
      trail: trailInfo,
      discussion: discussion,
      checkpoints: enrichedCheckpoints,
    });
  } catch (err) {
    if (isGitHubAuthError(err)) {
      return c.json({ error: "GitHub token expired" }, 401);
    }
    console.error(`Failed to fetch trail ${trailId}:`, err);
    recordSpanError(err);
    return c.json({ error: "Failed to fetch trail" }, 500);
  }
});

