        return c.json({
          collaborators: user.github_login ? [{ login: user.github_login }] : [],
        });
      }
      throw new Error(`Failed to fetch collaborators: ${response.status}`);
    }

    const data = await response.json<Array<{ login: string; avatar_url: string }>>();

    return c.json({
      collaborators: data.map((c) => ({
        login: c.login,
        avatar_url: c.avatar_url,
