  1→// Turbopuffer vector search client for checkpoints
  2→// Uses hybrid search: OpenAI embeddings (cosine similarity) + BM25 full-text search,
  3→// combined via Reciprocal Rank Fusion (RRF) for best results on both
  4→// semantic and exact keyword queries.
  5→
  6→const EMBEDDING_MODEL = "text-embedding-3-small";
  7→const EMBEDDING_DIMENSIONS = 1536;
  8→const MAX_EMBEDDING_CHARS = 25000; // ~8K tokens, text-embedding-3-small limit is 8192 tokens
  9→const MAX_FILTERABLE_BYTES = 3800; // Turbopuffer 4 KiB limit on filterable attributes
 10→const MAX_TEXT_BYTES = 500_000; // text field is non-filterable (8 MiB limit), generous cap for BM25
 11→
 12→export interface TurbopufferSearchResult {
 13→  checkpoint_id: string;
 14→}
 15→
 16→// v1 API response: bare array with nested attributes
 17→interface TurbopufferV1Row {
 18→  id: number;
 19→  dist: number;
 20→  attributes: {
 21→    checkpoint_id?: string;
 22→  };
 23→}
 24→
 25→// v2 API response: { rows: [...] } with flat attributes
 26→interface TurbopufferV2Row {
 27→  id: number;
 28→  $dist: number;
 29→  checkpoint_id?: string;
 30→}
 31→
 32→interface TurbopufferV2Response {
 33→  rows: TurbopufferV2Row[];
 34→}
 35→
 36→// Normalized row used internally
 37→interface SearchRow {
 38→  checkpoint_id: string | undefined;
 39→  dist: number;
 40→}
 41→
 42→function truncateToBytes(str: string | null, maxBytes: number): string | null {
 43→  if (str === null) return null;
 44→  if (str.length <= maxBytes) return str;
 45→  const encoder = new TextEncoder();
 46→  const encoded = encoder.encode(str);
 47→  if (encoded.length <= maxBytes) return str;
 48→  const truncated = encoded.slice(0, maxBytes);
 49→  const decoder = new TextDecoder();
 50→  return decoder.decode(truncated);
 51→}
 52→
 53→function buildSearchText(checkpoint: {
 54→  prompt: string | null;
 55→  commit_message: string | null;
 56→  files_touched: string[] | null;
 57→  transcript?: string | null;
 58→}): string {
 59→  const parts: string[] = [];
 60→  if (checkpoint.prompt) {
 61→    parts.push(`Prompt: ${checkpoint.prompt}`);
 62→  }
 63→  if (checkpoint.commit_message) {
 64→    parts.push(`Commit: ${checkpoint.commit_message}`);
 65→  }
 66→  if (checkpoint.files_touched) {
 67→    parts.push(`Files: ${checkpoint.files_touched.join(", ")}`);
 68→  }
 69→  if (checkpoint.transcript) {
 70→    parts.push(`Transcript: ${checkpoint.transcript}`);
 71→  }
 72→  return parts.join("\n");
 73→}
 74→
 75→// Hash checkpoint_id to a deterministic numeric ID for Turbopuffer
 76→// Uses FNV-1a 32-bit hash for fast, well-distributed IDs
 77→function hashToNumericId(checkpointId: string): number {
 78→  let hash = 0x811c9dc5; // FNV offset basis
 79→  for (let i = 0; i < checkpointId.length; i++) {
 80→    hash ^= checkpointId.charCodeAt(i);
 81→    hash = Math.imul(hash, 0x01000193); // FNV prime
 82→  }
 83→  return hash >>> 0; // unsigned 32-bit
 84→}
 85→
 86→async function embedTexts(
 87→  openaiApiKey: string,
 88→  texts: string[],
 89→): Promise<number[][]> {
 90→  const resp = await fetch("https://api.openai.com/v1/embeddings", {
 91→    method: "POST",
 92→    headers: {
 93→      Authorization: `Bearer ${openaiApiKey}`,
 94→      "Content-Type": "application/json",
 95→    },
 96→    body: JSON.stringify({
 97→      model: EMBEDDING_MODEL,
 98→      input: texts,
 99→      dimensions: EMBEDDING_DIMENSIONS,
100→    }),
101→  });
102→
103→  if (!resp.ok) {
104→    const err = await resp.text().catch(() => "");
105→    throw new Error(`OpenAI embedding failed (${resp.status}): ${err}`);
106→  }
107→
108→  const result = (await resp.json()) as {
109→    data: Array<{ index: number; embedding: number[] }>;
110→  };
111→  return result.data
112→    .sort((a, b) => a.index - b.index)
113→    .map((item) => item.embedding);
114→}
115→
116→async function embedQuery(openaiApiKey: string, text: string): Promise<number[]> {
117→  const resp = await fetch("https://api.openai.com/v1/embeddings", {
118→    method: "POST",
119→    headers: {
120→      Authorization: `Bearer ${openaiApiKey}`,
121→      "Content-Type": "application/json",
122→    },
123→    body: JSON.stringify({
124→      model: EMBEDDING_MODEL,
125→      input: text,
126→      dimensions: EMBEDDING_DIMENSIONS,
127→    }),
128→  });
129→
130→  if (!resp.ok) {
131→    const err = await resp.text().catch(() => "");
132→    throw new Error(`OpenAI embedding failed (${resp.status}): ${err}`);
133→  }
134→
135→  const result = (await resp.json()) as { data: Array<{ embedding: number[] }> };
136→  return result.data[0].embedding;
137→}
138→
139→// RRF constant — standard value that prevents top-ranked items from dominating
140→const RRF_K = 60;
141→
142→export async function searchCheckpoints(
143→  turbopufferApiKey: string,
144→  openaiApiKey: string,
145→  githubId: number,
146→  query: string,
147→  filters?: { branch?: string },
148→  limit: number = 50,
149→): Promise<TurbopufferSearchResult[]> {
150→  const namespace = `checkpoints-gh-${githubId}`;
151→
152→  const headers = {
153→    Authorization: `Bearer ${turbopufferApiKey}`,
154→    "Content-Type": "application/json",
155→  };
156→
157→  const branchFilters = filters?.branch
158→    ? { branch: [["Eq", filters.branch]] }
159→    : undefined;
160→
161→  // Fire vector + BM25 queries in parallel, gracefully degrade if either fails
162→  const [vectorResult, bm25Result] = await Promise.all([
163→    // Vector cosine similarity (v1 API)
164→    (async (): Promise<{ rows: SearchRow[]; error?: string }> => {
165→      try {
166→        const vector = await embedQuery(openaiApiKey, query);
167→        const url = `https://api.turbopuffer.com/v1/vectors/${encodeURIComponent(namespace)}/query`;
168→        const body: Record<string, unknown> = {
169→          vector,
170→          top_k: limit,
171→          distance_metric: "cosine_distance",
172→          include_attributes: ["checkpoint_id"],
173→        };
174→        if (branchFilters) body.filters = branchFilters;
175→
176→        const resp = await fetch(url, {
177→          method: "POST",
178→          headers,
179→          body: JSON.stringify(body),
180→        });
181→        if (!resp.ok) {
182→          const text = await resp.text().catch(() => "");
183→          return { rows: [], error: `vector query failed (${resp.status}): ${text}` };
184→        }
185→        const rows = (await resp.json()) as TurbopufferV1Row[];
186→        return { rows: rows.map((r) => ({ checkpoint_id: r.attributes?.checkpoint_id, dist: r.dist })) };
187→      } catch (err) {
188→        return { rows: [], error: `vector query error: ${err instanceof Error ? err.message : String(err)}` };
189→      }
190→    })(),
191→
192→    // BM25 full-text search (v2 API)
193→    (async (): Promise<{ rows: SearchRow[]; error?: string }> => {
194→      try {
195→        const url = `https://api.turbopuffer.com/v2/namespaces/${encodeURIComponent(namespace)}/query`;
196→        const body: Record<string, unknown> = {
197→          rank_by: ["text", "BM25", query],
198→          top_k: limit,
199→          include_attributes: ["checkpoint_id"],
200→        };
201→        if (branchFilters) body.filters = branchFilters;
202→
203→        const resp = await fetch(url, {
204→          method: "POST",
205→          headers,
206→          body: JSON.stringify(body),
207→        });
208→        if (!resp.ok) {
209→          const text = await resp.text().catch(() => "");
210→          return { rows: [], error: `BM25 query failed (${resp.status}): ${text}` };
211→        }
212→        const data = (await resp.json()) as TurbopufferV2Response;
213→        return { rows: data.rows.map((r) => ({ checkpoint_id: r.checkpoint_id, dist: r.$dist })) };
214→      } catch (err) {
215→        return { rows: [], error: `BM25 query error: ${err instanceof Error ? err.message : String(err)}` };
216→      }
217→    })(),
218→  ]);
219→
220→  const vectorResults = vectorResult.rows;
221→  const bm25Results = bm25Result.rows;
222→
223→  if (vectorResult.error) console.warn(`[search] ${vectorResult.error}`);
224→  if (bm25Result.error) console.warn(`[search] ${bm25Result.error}`);
225→
226→  // If both failed, return empty so client falls back to local filtering
227→  if (vectorResults.length === 0 && bm25Results.length === 0) {
228→    console.warn(`[search] both sources returned no results`);
229→    return [];
230→  }
231→
232→  console.log(`[search] query="${query}" namespace=${namespace}`);
233→  console.log(`[search] vector results: ${vectorResults.length}, bm25 results: ${bm25Results.length}`);
234→
235→  // Log top results from each source with their raw scores
236→  const topN = 5;
237→  if (vectorResults.length > 0) {
238→    console.log(`[search] top ${topN} vector (cosine dist):`,
239→      vectorResults.slice(0, topN).map((r, i) => ({
240→        rank: i + 1,
241→        checkpoint_id: r.checkpoint_id?.slice(0, 8),
242→        dist: r.dist?.toFixed(4),
243→      })),
244→    );
245→  }
246→  if (bm25Results.length > 0) {
247→    console.log(`[search] top ${topN} bm25:`,
248→      bm25Results.slice(0, topN).map((r, i) => ({
249→        rank: i + 1,
250→        checkpoint_id: r.checkpoint_id?.slice(0, 8),
251→        dist: r.dist?.toFixed(4),
252→      })),
253→    );
254→  }
255→
256→  // Merge via Reciprocal Rank Fusion (RRF)
257→  // score(doc) = 1/(k + rank_vector) + 1/(k + rank_bm25)
258→  const scores = new Map<string, { rrf: number; vectorRank: number | null; bm25Rank: number | null }>();
259→
260→  for (let rank = 0; rank < vectorResults.length; rank++) {
261→    const id = vectorResults[rank].checkpoint_id;
262→    if (id) {
263→      const entry = scores.get(id) ?? { rrf: 0, vectorRank: null, bm25Rank: null };
264→      entry.rrf += 1 / (RRF_K + rank + 1);
265→      entry.vectorRank = rank + 1;
266→      scores.set(id, entry);
267→    }
268→  }
269→
270→  for (let rank = 0; rank < bm25Results.length; rank++) {
271→    const id = bm25Results[rank].checkpoint_id;
272→    if (id) {
273→      const entry = scores.get(id) ?? { rrf: 0, vectorRank: null, bm25Rank: null };
274→      entry.rrf += 1 / (RRF_K + rank + 1);
275→      entry.bm25Rank = rank + 1;
276→      scores.set(id, entry);
277→    }
278→  }
279→
280→  // Sort by RRF score descending, take top `limit`
281→  const sorted = [...scores.entries()]
282→    .sort((a, b) => b[1].rrf - a[1].rrf)
283→    .slice(0, limit);
284→
285→  // Log final merged results
286→  console.log(`[search] top ${topN} RRF merged:`,
287→    sorted.slice(0, topN).map(([id, s]) => ({
288→      checkpoint_id: id.slice(0, 8),
289→      rrf: s.rrf.toFixed(6),
290→      vectorRank: s.vectorRank,
291→      bm25Rank: s.bm25Rank,
292→      source: s.vectorRank && s.bm25Rank ? "both" : s.vectorRank ? "vector-only" : "bm25-only",
293→    })),
294→  );
295→
296→  return sorted.map(([checkpoint_id]) => ({ checkpoint_id }));
297→}
298→
299→// Index checkpoints into Turbopuffer for vector search
300→// Builds search text, embeds via OpenAI, and upserts to Turbopuffer
301→// Returns the number of successfully indexed checkpoints
302→export async function indexCheckpoints(
303→  turbopufferApiKey: string,
304→  openaiApiKey: string,
305→  githubId: number,
306→  checkpoints: Array<{
307→    checkpoint_id: string;
308→    branch: string | null;
309→    agent: string | null;
310→    commit_author_username: string | null;
311→    created_at: string | null;
312→    commit_sha: string | null;
313→    commit_message: string | null;
314→    prompt: string | null;
315→    files_touched: string[] | null;
316→    transcript?: string | null;
317→  }>,
318→): Promise<number> {
319→  // Build search text and filter out empty entries
320→  const validCheckpoints: Array<{
321→    checkpoint: (typeof checkpoints)[number];
322→    text: string;
323→  }> = [];
324→
325→  for (const cp of checkpoints) {
326→    const text = buildSearchText(cp);
327→    if (text.trim()) {
328→      validCheckpoints.push({ checkpoint: cp, text });
329→    }
330→  }
331→
332→  if (validCheckpoints.length === 0) {
333→    return 0;
334→  }
335→
336→  // Truncate texts for embedding model token limit
337→  const embeddingTexts = validCheckpoints.map((v) =>
338→    v.text.slice(0, MAX_EMBEDDING_CHARS),
339→  );
340→
341→  // Embed all texts in one batch call
342→  const embeddings = await embedTexts(openaiApiKey, embeddingTexts);
343→
344→  // Build upsert payload (row-based format for Turbopuffer v1 API)
345→  const upserts = validCheckpoints.map(({ checkpoint, text }, i) => {
346→    const filesTouchedStr = checkpoint.files_touched?.join(", ") ?? null;
347→    return {
348→      id: hashToNumericId(checkpoint.checkpoint_id),
349→      vector: embeddings[i],
350→      attributes: {
