          return { rows: [], error: `BM25 query failed (${resp.status}): ${text}` };
        }
        const data = (await resp.json()) as TurbopufferV2Response;
        return { rows: data.rows.map((r) => ({ checkpoint_id: r.checkpoint_id, dist: r.$dist })) };
      } catch (err) {
        return { rows: [], error: `BM25 query error: ${err instanceof Error ? err.message : String(err)}` };
      }
    })(),
  ]);

  const vectorResults = vectorResult.rows;
  const bm25Results = bm25Result.rows;

  if (vectorResult.error) console.warn(`[search] ${vectorResult.error}`);
  if (bm25Result.error) console.warn(`[search] ${bm25Result.error}`);

  // If both failed, return empty so client falls back to local filtering
  if (vectorResults.length === 0 && bm25Results.length === 0) {
    console.warn(`[search] both sources returned no results`);
    return [];
  }

  console.log(`[search] query="${query}" namespace=${namespace}`);
  console.log(`[search] vector results: ${vectorResults.length}, bm25 results: ${bm25Results.length}`);

  // Log top results from each source with their raw scores
  const topN = 5;
  if (vectorResults.length > 0) {
    console.log(`[search] top ${topN} vector (cosine dist):`,
      vectorResults.slice(0, topN).map((r, i) => ({
        rank: i + 1,
        checkpoint_id: r.checkpoint_id?.slice(0, 8),
        dist: r.dist?.toFixed(4),
      })),
    );
  }
  if (bm25Results.length > 0) {
    console.log(`[search] top ${topN} bm25:`,
      bm25Results.slice(0, topN).map((r, i) => ({
        rank: i + 1,
        checkpoint_id: r.checkpoint_id?.slice(0, 8),
        dist: r.dist?.toFixed(4),
      })),
    );
  }

  // Merge via Reciprocal Rank Fusion (RRF)
  // score(doc) = 1/(k + rank_vector) + 1/(k + rank_bm25)
  const scores = new Map<string, { rrf: number; vectorRank: number | null; bm25Rank: number | null }>();

  for (let rank = 0; rank < vectorResults.length; rank++) {
    const id = vectorResults[rank].checkpoint_id;
    if (id) {
      const entry = scores.get(id) ?? { rrf: 0, vectorRank: null, bm25Rank: null };
      entry.rrf += 1 / (RRF_K + rank + 1);
      entry.vectorRank = rank + 1;
      scores.set(id, entry);
    }
  }

  for (let rank = 0; rank < bm25Results.length; rank++) {
    const id = bm25Results[rank].checkpoint_id;
    if (id) {
      const entry = scores.get(id) ?? { rrf: 0, vectorRank: null, bm25Rank: null };
      entry.rrf += 1 / (RRF_K + rank + 1);
      entry.bm25Rank = rank + 1;
      scores.set(id, entry);
    }
  }

  // Sort by RRF score descending, take top `limit`
  const sorted = [...scores.entries()]
    .sort((a, b) => b[1].rrf - a[1].rrf)
    .slice(0, limit);

  // Log final merged results
  console.log(`[search] top ${topN} RRF merged:`,
    sorted.slice(0, topN).map(([id, s]) => ({
      checkpoint_id: id.slice(0, 8),
      rrf: s.rrf.toFixed(6),
      vectorRank: s.vectorRank,
      bm25Rank: s.bm25Rank,
      source: s.vectorRank && s.bm25Rank ? "both" : s.vectorRank ? "vector-only" : "bm25-only",
    })),
  );

  return sorted.map(([checkpoint_id]) => ({ checkpoint_id }));
}

// Index checkpoints into Turbopuffer for vector search
// Builds search text, embeds via OpenAI, and upserts to Turbopuffer
// Returns the number of successfully indexed checkpoints
export async function indexCheckpoints(
  turbopufferApiKey: string,
  openaiApiKey: string,
  githubId: number,
  checkpoints: Array<{
    checkpoint_id: string;
    branch: string | null;
    agent: string | null;
    commit_author_username: string | null;
    created_at: string | null;
    commit_sha: string | null;
    commit_message: string | null;
    prompt: string | null;
    files_touched: string[] | null;
    transcript?: string | null;
  }>,
): Promise<number> {
  // Build search text and filter out empty entries
  const validCheckpoints: Array<{
    checkpoint: (typeof checkpoints)[number];
    text: string;
  }> = [];

  for (const cp of checkpoints) {
    const text = buildSearchText(cp);
    if (text.trim()) {
      validCheckpoints.push({ checkpoint: cp, text });
    }
  }

  if (validCheckpoints.length === 0) {
    return 0;
  }

  // Truncate texts for embedding model token limit
  const embeddingTexts = validCheckpoints.map((v) =>
    v.text.slice(0, MAX_EMBEDDING_CHARS),
  );

  // Embed all texts in one batch call
  const embeddings = await embedTexts(openaiApiKey, embeddingTexts);

  // Build upsert payload (row-based format for Turbopuffer v1 API)
  const upserts = validCheckpoints.map(({ checkpoint, text }, i) => {
    const filesTouchedStr = checkpoint.files_touched?.join(", ") ?? null;
    return {
      id: hashToNumericId(checkpoint.checkpoint_id),
      vector: embeddings[i],
      attributes: {
        checkpoint_id: checkpoint.checkpoint_id,
        branch: checkpoint.branch,
        agent: checkpoint.agent,
        author: checkpoint.commit_author_username,
        created_at: checkpoint.created_at,
        commit_sha: checkpoint.commit_sha,
        commit_message: truncateToBytes(
          checkpoint.commit_message,
          MAX_FILTERABLE_BYTES,
        ),
        prompt: truncateToBytes(checkpoint.prompt, MAX_FILTERABLE_BYTES),
        files_touched: truncateToBytes(filesTouchedStr, MAX_FILTERABLE_BYTES),
        text: truncateToBytes(text, MAX_TEXT_BYTES),
      },
    };
  });

  // Upsert to Turbopuffer
  const namespace = `checkpoints-gh-${githubId}`;
  const url = `https://api.turbopuffer.com/v1/vectors/${encodeURIComponent(namespace)}`;

  const resp = await fetch(url, {
    method: "POST",
    headers: {
      Authorization: `Bearer ${turbopufferApiKey}`,
      "Content-Type": "application/json",
    },
    body: JSON.stringify({
      upserts,
      distance_metric: "cosine_distance",
      schema: {
        text: {
          type: "string",
          filterable: false,
          full_text_search: {
            language: "english",
            stemming: true,
            remove_stopwords: true,
          },
        },
      },
    }),
  });

  if (!resp.ok) {
    const errText = await resp.text().catch(() => "");
    throw new Error(`Turbopuffer upsert failed (${resp.status}): ${errText}`);
  }

  return validCheckpoints.length;
}

