import { timingSafeEqual as nodeTimingSafeEqual } from "crypto";
import { getTestDbClient, getTestKysely, resetMySQLDatabase } from "./planetscale/mysql-test-client";
import { Db } from "../src/lib/db/db-types";
import { beforeAll, beforeEach } from "vitest";

// Polyfill crypto.subtle.timingSafeEqual for Node.js test environment
// Cloudflare Workers provides this natively, but Node.js doesn't
if (typeof crypto.subtle.timingSafeEqual !== "function") {
  (crypto.subtle as unknown as Record<string, unknown>).timingSafeEqual = (
    a: ArrayBuffer | ArrayBufferView,
    b: ArrayBuffer | ArrayBufferView
  ): boolean => {
    const aBuffer = a instanceof ArrayBuffer ? new Uint8Array(a) : new Uint8Array(a.buffer, a.byteOffset, a.byteLength);
    const bBuffer = b instanceof ArrayBuffer ? new Uint8Array(b) : new Uint8Array(b.buffer, b.byteOffset, b.byteLength);
    return nodeTimingSafeEqual(aBuffer, bBuffer);
  };
}

