 53→export function buildSearchText(checkpoint: {
 54→  prompt: string | null;
 55→  commit_message: string | null;
 56→  files_touched: string[] | null;
 57→  transcript?: string | null;
 58→}): string {
 59→  const parts: string[] = [];
 60→  if (checkpoint.prompt) {
 61→    parts.push(`Prompt: ${checkpoint.prompt}`);
 62→  }
 63→  if (checkpoint.commit_message) {
 64→    parts.push(`Commit: ${checkpoint.commit_message}`);
 65→  }
 66→  if (checkpoint.files_touched) {
 67→    parts.push(`Files: ${checkpoint.files_touched.join(", ")}`);
 68→  }
 69→  if (checkpoint.transcript) {
 70→    parts.push(`Transcript: ${checkpoint.transcript}`);
 71→  }
 72→  return parts.join("\n");
 73→}
