1221→        errors: sessionDataResult.errors,
1222→      });
1223→    }
1224→
1225→    // Upsert full checkpoint records (COALESCE preserves existing data)
1226→    const checkpointData = buildCheckpointDataFromSessions(checkpointIds, sessionDataResult, branch);
1227→    const checkpointsProcessed = await db.checkpoints.upsertBatch(repoRecord.id, checkpointData);
1228→
1229→    // Upsert commits for the global repo (once, not per-user)
1230→    const successCount = await db.checkpoints.upsertCommitBatch(repoRecord.id, branch, commitDataArray);
1231→
1232→    // Queue checkpoints for search indexing (non-blocking, best-effort)
1233→    if (env.SEARCH_INDEX_QUEUE) {
1234→      await env.SEARCH_INDEX_QUEUE.send({
1235→        repoId: repoRecord.id,
1236→        checkpointIds: checkpointCommits.map((c) => c.checkpointId),
1237→        queuedAt: new Date().toISOString(),
1238→      } satisfies SearchIndexMessage);
1239→    }
1240→
1241→    // Recalculate checkpoint count
1242→    if (successCount > 0) {
1243→      await db.checkpoints.recalculateCount(repoRecord.id);
1244→    }
1245→
1246→    if (checkpointsProcessed > 0) {
1247→      logCheckpointMetric("checkpoints_upserted", { repo: repoFullName, branch, count: checkpointsProcessed });
1248→    }
