116→async function embedQuery(openaiApiKey: string, text: string): Promise<number[]> {
117→  const resp = await fetch("https://api.openai.com/v1/embeddings", {
118→    method: "POST",
119→    headers: {
120→      Authorization: `Bearer ${openaiApiKey}`,
121→      "Content-Type": "application/json",
122→    },
123→    body: JSON.stringify({
124→      model: EMBEDDING_MODEL,
125→      input: text,
126→      dimensions: EMBEDDING_DIMENSIONS,
127→    }),
128→  });
129→
130→  if (!resp.ok) {
131→    const err = await resp.text().catch(() => "");
132→    throw new Error(`OpenAI embedding failed (${resp.status}): ${err}`);
133→  }
134→
135→  const result = (await resp.json()) as { data: Array<{ embedding: number[] }> };
136→  return result.data[0].embedding;
137→}
138→
139→// RRF constant — standard value that prevents top-ranked items from dominating
140→export const RRF_K = 60;
141→
142→export interface RRFResult {
143→  checkpoint_id: string;
144→  rrf: number;
145→  vectorRank: number | null;
146→  bm25Rank: number | null;
147→}
148→
149→// Merge two ranked lists via Reciprocal Rank Fusion
150→// score(doc) = 1/(k + rank_vector) + 1/(k + rank_bm25)
151→export function mergeRRF(
152→  vectorResults: SearchRow[],
153→  bm25Results: SearchRow[],
154→  limit: number,
155→): RRFResult[] {
156→  const scores = new Map<string, { rrf: number; vectorRank: number | null; bm25Rank: number | null }>();
157→
158→  for (let rank = 0; rank < vectorResults.length; rank++) {
159→    const id = vectorResults[rank].checkpoint_id;
160→    if (id) {
161→      const entry = scores.get(id) ?? { rrf: 0, vectorRank: null, bm25Rank: null };
162→      entry.rrf += 1 / (RRF_K + rank + 1);
163→      entry.vectorRank = rank + 1;
164→      scores.set(id, entry);
165→    }
166→  }
167→
168→  for (let rank = 0; rank < bm25Results.length; rank++) {
169→    const id = bm25Results[rank].checkpoint_id;
170→    if (id) {
171→      const entry = scores.get(id) ?? { rrf: 0, vectorRank: null, bm25Rank: null };
172→      entry.rrf += 1 / (RRF_K + rank + 1);
173→      entry.bm25Rank = rank + 1;
174→      scores.set(id, entry);
175→    }
176→  }
177→
178→  return [...scores.entries()]
179→    .sort((a, b) => b[1].rrf - a[1].rrf)
180→    .slice(0, limit)
181→    .map(([checkpoint_id, s]) => ({ checkpoint_id, ...s }));
182→}
