117→// ============================================================================
118→// Debounce helper
119→// ============================================================================
120→
121→interface DebouncedFunction<T extends (...args: unknown[]) => void> {
122→  (...args: Parameters<T>): void;
123→  cancel: () => void;
124→}
125→
126→function useDebouncedCallback<T extends (...args: unknown[]) => void>(
127→  callback: T,
128→  delay: number,
129→): DebouncedFunction<T> {
130→  const timeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);
131→  const callbackRef = useRef(callback);
132→
133→  // Keep callback ref updated
134→  useEffect(() => {
135→    callbackRef.current = callback;
136→  }, [callback]);
137→
138→  const cancel = useCallback(() => {
139→    if (timeoutRef.current) {
140→      clearTimeout(timeoutRef.current);
141→      timeoutRef.current = null;
142→    }
143→  }, []);
144→
145→  const debouncedFn = useCallback(
146→    (...args: Parameters<T>) => {
147→      if (timeoutRef.current) {
148→        clearTimeout(timeoutRef.current);
149→      }
150→      timeoutRef.current = setTimeout(() => {
151→        callbackRef.current(...args);
152→      }, delay);
153→    },
154→    [delay],
155→  );
156→
157→  // Cleanup on unmount
158→  useEffect(() => {
159→    return () => {
160→      if (timeoutRef.current) {
161→        clearTimeout(timeoutRef.current);
162→      }
163→    };
164→  }, []);
165→
166→  // Return function with cancel method attached
167→  return useMemo(
168→    () => Object.assign(debouncedFn, { cancel }) as DebouncedFunction<T>,
169→    [debouncedFn, cancel],
170→  );
171→}
