173→// ============================================================================
174→// Combobox Root
175→// ============================================================================
176→
177→interface ComboboxProps {
178→  children: ReactNode;
179→  options: ComboboxOption[];
180→  /** Allow multiple selections. When false, closes on selection. */
181→  multiple?: boolean;
182→  /** Size variant: small, default, or large. */
183→  size?: ComboboxSize;
184→  value?: string[];
185→  defaultValue?: string[];
186→  onChange?: (selectedIds: string[]) => void;
187→  open?: boolean;
188→  defaultOpen?: boolean;
189→  onOpenChange?: (open: boolean) => void;
190→}
191→
192→export function Combobox({
193→  children,
194→  options,
195→  multiple = false,
196→  size = "default",
197→  value,
198→  defaultValue = [],
199→  onChange,
200→  open,
201→  defaultOpen = false,
202→  onOpenChange,
203→}: ComboboxProps) {
204→  // Generate unique ID for this instance
205→  const instanceId = useId();
206→
207→  // Controlled/uncontrolled open state
208→  const [uncontrolledOpen, setUncontrolledOpen] = useState(defaultOpen);
209→  const isOpen = open ?? uncontrolledOpen;
210→  const setIsOpen = useCallback(
211→    (newOpen: boolean) => {
212→      setUncontrolledOpen(newOpen);
213→      onOpenChange?.(newOpen);
214→    },
215→    [onOpenChange],
216→  );
217→
218→  // Controlled/uncontrolled selection state
219→  const [uncontrolledSelected, setUncontrolledSelected] = useState<Set<string>>(
220→    () => new Set(defaultValue),
221→  );
222→  const selectedIds = useMemo(
223→    () => (value ? new Set(value) : uncontrolledSelected),
224→    // eslint-disable-next-line react-hooks/exhaustive-deps -- value is an array; compare by contents (JSON avoids comma-in-id ambiguity from join)
225→    [value == null ? undefined : JSON.stringify(value), uncontrolledSelected],
226→  );
227→  const setSelectedIds = useCallback(
228→    (ids: Set<string>) => {
229→      setUncontrolledSelected(ids);
230→      onChange?.(Array.from(ids));
231→    },
232→    [onChange],
233→  );
234→
235→  // Filter state
236→  const [filterText, setFilterText] = useState("");
237→  const [activeIndex, setActiveIndex] = useState<number | null>(0);
238→
239→  // Screen reader announcements
240→  const [announcement, setAnnouncement] = useState("");
241→
242→  const resetAnnouncement = useCallback(() => {
243→    setAnnouncement("");
244→  }, []);
245→
246→  const announce = useCallback((message: string) => {
247→    setAnnouncement(message);
248→  }, []);
249→
250→  // Filter options based on input
251→  const filteredOptions = useMemo(() => {
252→    const searchTerm = filterText.toLowerCase().trim();
253→    if (!searchTerm) return options;
254→    return options.filter((opt) =>
255→      opt.label.toLowerCase().includes(searchTerm),
256→    );
257→  }, [options, filterText]);
258→
259→  // Timer refs for cleanup
260→  const initialFocusTimerRef = useRef<ReturnType<typeof setTimeout> | null>(
261→    null,
262→  );
263→  const filterResultsTimerRef = useRef<ReturnType<typeof setTimeout> | null>(
264→    null,
265→  );
266→
267→  // Clear all announcement timers
268→  const clearAnnouncementTimers = useCallback(() => {
269→    if (initialFocusTimerRef.current) {
270→      clearTimeout(initialFocusTimerRef.current);
271→      initialFocusTimerRef.current = null;
272→    }
273→    if (filterResultsTimerRef.current) {
274→      clearTimeout(filterResultsTimerRef.current);
275→      filterResultsTimerRef.current = null;
276→    }
277→  }, []);
278→
279→  // Announce initial focus (called when input receives focus)
280→  // Format: "Focus on filter text box and list of labels. Focused item, {name}, {index} of {total}"
281→  const announceInitialFocus = useCallback(() => {
282→    clearAnnouncementTimers();
283→    initialFocusTimerRef.current = setTimeout(() => {
284→      const items = filteredOptions;
285→      const currentActiveIndex = activeIndex ?? 0;
286→      const activeItem = items[currentActiveIndex];
287→
288→      if (activeItem) {
289→        const announcementText = `Focus on filter text box and list of labels. Focused item, ${activeItem.label}, ${currentActiveIndex + 1} of ${items.length}`;
290→        announce(announcementText);
291→      } else if (items.length === 0) {
292→        announce("No items.");
293→      }
294→    }, 500);
295→  }, [filteredOptions, activeIndex, announce, clearAnnouncementTimers]);
296→
297→  // Announce filter results (debounced, called after typing)
298→  // Format: "List updated. Focused item, {name}, 1 of {total}" or "No items."
299→  const announceFilterResultsInternal = useCallback(() => {
300→    // Clear any pending timers before setting new one
301→    clearAnnouncementTimers();
302→    filterResultsTimerRef.current = setTimeout(() => {
303→      const items = filteredOptions;
304→      if (items.length > 0) {
305→        const firstItem = items[0];
306→        const announcementText = `List updated. Focused item, ${firstItem.label}, 1 of ${items.length}`;
307→        announce(announcementText);
308→      } else {
309→        announce("No items.");
310→      }
311→    }, 500);
312→  }, [filteredOptions, announce, clearAnnouncementTimers]);
313→
314→  const debouncedAnnounceFilterResults = useDebouncedCallback(
315→    announceFilterResultsInternal,
316→    1000,
317→  );
318→
319→  // Refs for list navigation
320→  const listRef = useRef<(HTMLElement | null)[]>([]);
321→  const inputRef = useRef<HTMLInputElement>(null);
322→
323→  // Floating UI setup
324→  const { refs, floatingStyles, context } = useFloating({
325→    open: isOpen,
326→    onOpenChange: setIsOpen,
327→    middleware: [offset(4), flip(), shift({ padding: 8 })],
328→    whileElementsMounted: autoUpdate,
329→    placement: "bottom-start",
330→  });
331→
332→  const click = useClick(context);
333→  const dismiss = useDismiss(context);
334→  const role = useRole(context, { role: "listbox" });
335→  const listNavigation = useListNavigation(context, {
336→    listRef,
337→    activeIndex,
338→    onNavigate: setActiveIndex,
339→    virtual: true,
340→    loop: true,
341→  });
342→
343→  const { getReferenceProps, getFloatingProps, getItemProps } = useInteractions(
344→    [click, dismiss, role, listNavigation],
345→  );
346→
347→  // Select/toggle an option (no announcement - let aria-selected do the work)
348→  const selectOption = useCallback(
349→    (id: string) => {
350→      const option = options.find((o) => o.id === id);
351→      if (option?.disabled) return;
352→
353→      if (multiple) {
354→        // Multi-select: toggle selection
355→        const newSelected = new Set(selectedIds);
356→        const wasSelected = newSelected.has(id);
357→
358→        if (wasSelected) {
359→          newSelected.delete(id);
360→        } else {
361→          newSelected.add(id);
362→        }
363→
364→        setSelectedIds(newSelected);
365→      } else {
366→        // Single-select: replace selection and close
367→        const newSelected = new Set([id]);
368→        setSelectedIds(newSelected);
369→
370→        // Close after selection for single-select
371→        setIsOpen(false);
372→      }
373→    },
374→    [selectedIds, setSelectedIds, options, multiple, setIsOpen],
375→  );
376→
377→  // Reset filter, active index, and announcement when opening/closing
378→  useEffect(() => {
379→    if (isOpen) {
380→      // Reset announcement on open
381→      resetAnnouncement();
382→      setActiveIndex(0);
383→    } else {
384→      // Reset on close - clear timers to prevent stale announcements
385→      clearAnnouncementTimers();
386→      debouncedAnnounceFilterResults.cancel();
387→      resetAnnouncement();
388→      setFilterText("");
389→      setActiveIndex(0);
390→    }
391→  }, [
392→    isOpen,
393→    resetAnnouncement,
394→    clearAnnouncementTimers,
395→    debouncedAnnounceFilterResults,
396→  ]);
397→
398→  const contextValue = useMemo<ComboboxContextValue>(
399→    () => ({
400→      isOpen,
401→      setIsOpen,
402→      selectedIds,
403→      selectOption,
404→      activeIndex,
405→      setActiveIndex,
406→      filterText,
407→      setFilterText,
408→      filteredOptions,
409→      multiple,
410→      size,
411→      listRef,
412→      inputRef,
413→      getReferenceProps,
414→      getFloatingProps,
415→      getItemProps,
416→      refs,
417→      floatingStyles,
418→      context,
419→      announce,
420→      resetAnnouncement,
421→      announceInitialFocus,
422→      debouncedAnnounceFilterResults,
423→      instanceId,
424→    }),
425→    [
426→      isOpen,
427→      setIsOpen,
428→      selectedIds,
429→      selectOption,
430→      activeIndex,
431→      setActiveIndex,
432→      filterText,
433→      setFilterText,
434→      filteredOptions,
435→      multiple,
436→      size,
437→      getReferenceProps,
438→      getFloatingProps,
439→      getItemProps,
440→      refs,
441→      floatingStyles,
442→      context,
443→      announce,
444→      resetAnnouncement,
445→      announceInitialFocus,
446→      debouncedAnnounceFilterResults,
447→      instanceId,
448→    ],
449→  );
450→
451→  return (
452→    <ComboboxContext.Provider value={contextValue}>
453→      {children}
454→      {/* Screen reader live region */}
455→      <div
456→        role="status"
457→        aria-live="polite"
458→        aria-atomic="true"
459→        className="sr-only"
460→      >
461→        {announcement}
462→      </div>
463→    </ComboboxContext.Provider>
464→  );
465→}
