467→// ============================================================================
468→// Combobox Trigger
469→// ============================================================================
470→
471→interface ComboboxTriggerProps {
472→  children?: ReactNode;
473→  className?: string;
474→  placeholder?: string;
475→  size?: "small" | "medium" | "large";
476→  variant?: "outline" | "ghost" | "attention" | "danger";
477→  condensed?: boolean;
478→  /** Render as the child element instead of wrapping in a Button. */
479→  asChild?: boolean;
480→}
481→
482→// Merge multiple refs into one callback ref
483→function mergeRefs<T>(...refs: (React.Ref<T> | undefined)[]): React.RefCallback<T> {
484→  return (node: T | null) => {
485→    refs.forEach((ref) => {
486→      if (typeof ref === "function") {
487→        ref(node);
488→      } else if (ref && typeof ref === "object") {
489→        (ref as React.MutableRefObject<T | null>).current = node;
490→      }
491→    });
492→  };
493→}
494→
495→// Compose event handlers, calling child's handler first
496→function composeEventHandlers<E>(
497→  childHandler: ((event: E) => void) | undefined,
498→  ourHandler: ((event: E) => void) | undefined,
499→): ((event: E) => void) | undefined {
500→  if (!childHandler && !ourHandler) return undefined;
501→  return (event: E) => {
502→    childHandler?.(event);
503→    ourHandler?.(event);
504→  };
505→}
506→
507→export const ComboboxTrigger = forwardRef<HTMLButtonElement, ComboboxTriggerProps>(
508→  function ComboboxTrigger({ children, className, placeholder = "Select options", size, variant = "outline", condensed, asChild }, ref) {
509→    const { refs, getReferenceProps, isOpen, selectedIds } = useComboboxContext();
510→
511→    const displayText = selectedIds.size > 0
512→      ? `${selectedIds.size} selected`
513→      : placeholder;
514→
515→    const referenceProps = getReferenceProps();
516→
517→    if (asChild && isValidElement(children)) {
518→      const child = children as ReactElement<Record<string, unknown>>;
519→      const childProps = child.props;
520→      const childRef = childProps.ref as React.Ref<HTMLElement> | undefined;
521→
522→      // Merge refs: floating-ui ref, forwarded ref, and child's existing ref
523→      const mergedRef = mergeRefs<HTMLElement>(
524→        refs.setReference as React.Ref<HTMLElement>,
525→        ref as React.Ref<HTMLElement>,
526→        childRef,
527→      );
528→
529→      // Compose event handlers from referenceProps with child's handlers
530→      const composedProps: Record<string, unknown> = {
531→        ref: mergedRef,
532→        "aria-haspopup": "listbox",
533→        "aria-expanded": isOpen,
534→      };
535→
536→      // Merge all referenceProps, composing event handlers
537→      for (const [key, value] of Object.entries(referenceProps)) {
538→        if (key.startsWith("on") && typeof value === "function") {
539→          composedProps[key] = composeEventHandlers(
540→            childProps[key] as ((event: unknown) => void) | undefined,
541→            value as (event: unknown) => void,
542→          );
543→        } else {
544→          composedProps[key] = value;
545→        }
546→      }
547→
548→      return cloneElement(child, composedProps);
549→    }
550→
551→    const setRefs = (node: HTMLButtonElement | HTMLAnchorElement | null) => {
552→      refs.setReference(node);
553→      if (typeof ref === "function") {
554→        ref(node as HTMLButtonElement | null);
555→      } else if (ref) {
556→        ref.current = node as HTMLButtonElement | null;
557→      }
558→    };
559→
560→    return (
561→      <Button
562→        ref={(node) => setRefs(node)}
563→        variant={variant}
564→        size={size}
565→        condensed={condensed}
566→        className={clsx("justify-between", className)}
567→        aria-haspopup="listbox"
568→        aria-expanded={isOpen}
569→        {...referenceProps}
570→      >
571→        {children ?? (
572→          <span className="flex items-center justify-between gap-1.5 w-full">
573→            <span className={clsx("truncate", selectedIds.size === 0 && "text-muted")}>
574→              {displayText}
575→            </span>
576→            <svg
577→              className={clsx(
578→                "w-4 h-4 text-muted transition-transform shrink-0",
579→                isOpen && "rotate-180",
580→              )}
581→              fill="none"
582→              viewBox="0 0 24 24"
583→              stroke="currentColor"
584→              aria-hidden="true"
585→            >
586→              <path
587→                strokeLinecap="round"
588→                strokeLinejoin="round"
589→                strokeWidth={2}
590→                d="M19 9l-7 7-7-7"
591→              />
592→            </svg>
593→          </span>
594→        )}
595→      </Button>
596→    );
597→  },
598→);
