610→export function ComboboxContent({
611→  children,
612→  className,
613→  label,
614→}: ComboboxContentProps) {
615→  const {
616→    isOpen,
617→    refs,
618→    floatingStyles,
619→    getFloatingProps,
620→    inputRef,
621→    context,
622→    size,
623→  } = useComboboxContext();
