658→// ============================================================================
659→// Combobox Input
660→// ============================================================================
661→
662→interface ComboboxInputProps {
663→  placeholder?: string;
664→  className?: string;
665→}
666→
667→export function ComboboxInput({
668→  placeholder = "Search...",
669→  className,
670→}: ComboboxInputProps) {
671→  const {
672→    filterText,
673→    setFilterText,
674→    filteredOptions,
675→    activeIndex,
676→    setActiveIndex,
677→    selectOption,
678→    inputRef,
679→    resetAnnouncement,
680→    announceInitialFocus,
681→    debouncedAnnounceFilterResults,
682→    instanceId,
683→  } = useComboboxContext();
684→
685→  const listboxId = `combobox-listbox-${instanceId}`;
686→
687→  const handleFocus = () => {
688→    announceInitialFocus();
689→  };
690→
691→  const handleBlur = () => {
692→    resetAnnouncement();
693→  };
694→
695→  const handleChange = (e: ChangeEvent<HTMLInputElement>) => {
696→    const newValue = e.target.value;
697→    setFilterText(newValue);
698→    // Always reset to first item when typing - the keyboard navigation
699→    // guards against empty results, and announcements handle "No items"
700→    setActiveIndex(0);
701→    // Debounced announcement of filter results
702→    debouncedAnnounceFilterResults();
703→  };
704→
705→  const handleKeyDown = (e: KeyboardEvent<HTMLInputElement>) => {
706→    // Guard against empty results
707→    if (filteredOptions.length === 0) return;
708→
709→    if (e.key === "ArrowDown") {
710→      e.preventDefault();
711→      if (activeIndex === null || activeIndex >= filteredOptions.length - 1) {
712→        setActiveIndex(0);
713→      } else {
714→        setActiveIndex(activeIndex + 1);
715→      }
716→    } else if (e.key === "ArrowUp") {
717→      e.preventDefault();
718→      if (activeIndex === null || activeIndex <= 0) {
719→        setActiveIndex(filteredOptions.length - 1);
720→      } else {
721→        setActiveIndex(activeIndex - 1);
722→      }
723→    } else if (e.key === "Enter" && activeIndex !== null) {
724→      e.preventDefault();
725→      const option = filteredOptions[activeIndex];
726→      if (option && !option.disabled) {
727→        selectOption(option.id);
728→      }
729→    }
730→  };
731→
732→  return (
733→    <div className="p-2 border-b border-default">
734→      <div className="relative">
735→        <SearchIcon
736→          className="absolute left-2.5 top-1/2 -translate-y-1/2 w-4 h-4 text-muted pointer-events-none"
737→          aria-hidden="true"
738→        />
739→        <input
740→          ref={inputRef}
741→          type="text"
742→          role="combobox"
743→          autoComplete="off"
744→          autoCorrect="off"
745→          autoCapitalize="off"
746→          spellCheck={false}
747→          aria-autocomplete="list"
748→          aria-controls={listboxId}
749→          aria-expanded="true"
750→          aria-activedescendant={
751→            activeIndex !== null
752→              ? `combobox-option-${instanceId}-${activeIndex}`
753→              : undefined
754→          }
755→          placeholder={placeholder}
756→          value={filterText}
757→          onChange={handleChange}
758→          onFocus={handleFocus}
759→          onBlur={handleBlur}
760→          onKeyDown={handleKeyDown}
761→          className={clsx(
762→            "w-full h-9 pl-8 pr-3",
763→            "bg-base border border-default rounded-md",
764→            "text-sm text-default placeholder:text-muted",
765→            "focus:outline-2 focus:-outline-offset-2 focus:outline-focus",
766→            className,
767→          )}
768→        />
769→      </div>
770→    </div>
771→  );
772→}
