  3→interface DiffViewerProps {
  4→  patch: string;
  5→  filename: string;
  6→  truncated?: boolean;
  7→  showHeader?: boolean;
  8→}
  9→
 10→interface DiffLine {
 11→  type: "add" | "remove" | "context" | "hunk" | "header";
 12→  content: string;
 13→  oldLineNum?: number;
 14→  newLineNum?: number;
 15→}
 16→
 17→function parsePatch(patch: string): DiffLine[] {
 18→  const lines = patch.split("\n");
 19→  const result: DiffLine[] = [];
 20→
 21→  let oldLine = 0;
 22→  let newLine = 0;
 23→
 24→  for (const line of lines) {
 25→    if (line.startsWith("@@")) {
 26→      // Hunk header: @@ -10,7 +10,9 @@
 27→      const match = line.match(/@@ -(\d+),?\d* \+(\d+),?\d* @@/);
 28→      if (match) {
 29→        oldLine = parseInt(match[1], 10);
 30→        newLine = parseInt(match[2], 10);
 31→      }
 32→      result.push({ type: "hunk", content: line });
 33→    } else if (line.startsWith("+")) {
 34→      result.push({
 35→        type: "add",
 36→        content: line.slice(1),
 37→        newLineNum: newLine++,
 38→      });
 39→    } else if (line.startsWith("-")) {
 40→      result.push({
 41→        type: "remove",
 42→        content: line.slice(1),
 43→        oldLineNum: oldLine++,
 44→      });
 45→    } else if (line.startsWith(" ")) {
 46→      result.push({
 47→        type: "context",
 48→        content: line.slice(1),
 49→        oldLineNum: oldLine++,
 50→        newLineNum: newLine++,
 51→      });
 52→    } else if (line.startsWith("diff ") || line.startsWith("index ")) {
 53→      result.push({ type: "header", content: line });
 54→    } else if (line === "\\ No newline at end of file") {
 55→      result.push({ type: "context", content: line });
 56→    } else if (line.trim() !== "") {
 57→      // Other content (like "... [truncated]")
 58→      result.push({ type: "context", content: line });
 59→    }
 60→  }
 61→
 62→  return result;
 63→}
 64→
 65→const lineStyles: Record<DiffLine["type"], string> = {
 66→  add: "bg-green-100 dark:bg-green-900/30 text-green-800 dark:text-green-200",
 67→  remove: "bg-red-100 dark:bg-red-900/30 text-red-800 dark:text-red-200",
 68→  context: "text-neutral-700 dark:text-neutral-300",
 69→  hunk: "bg-blue-50 dark:bg-blue-900/20 text-blue-600 dark:text-blue-400 font-medium",
 70→  header: "bg-neutral-100 dark:bg-neutral-800 text-neutral-500 dark:text-neutral-400",
 71→};
 72→
 73→const lineNumStyles: Record<DiffLine["type"], string> = {
 74→  add: "bg-green-200/50 dark:bg-green-800/30 text-green-700 dark:text-green-400",
 75→  remove: "bg-red-200/50 dark:bg-red-800/30 text-red-700 dark:text-red-400",
 76→  context: "bg-neutral-100 dark:bg-neutral-800 text-neutral-400 dark:text-neutral-500",
 77→  hunk: "bg-blue-100 dark:bg-blue-900/30 text-blue-500 dark:text-blue-400",
 78→  header: "bg-neutral-100 dark:bg-neutral-800 text-neutral-400 dark:text-neutral-500",
 79→};
 80→
 81→export function DiffViewer({ patch, filename, truncated, showHeader = true }: DiffViewerProps) {
 82→  const lines = useMemo(() => parsePatch(patch), [patch]);
 83→
 84→  return (
 85→    <div className={`${showHeader ? 'border border-default rounded' : ''} overflow-hidden text-xs`}>
 86→      {/* File header */}
 87→      {showHeader && (
 88→        <div className="bg-neutral-100 dark:bg-neutral-800 px-3 py-2 border-b border-default">
 89→          <span className="font-mono text-default">
 90→            {filename}
 91→          </span>
 92→        </div>
 93→      )}
 94→
 95→      {/* Diff content */}
 96→      <div className="overflow-x-auto">
 97→        <table className="w-full font-mono text-xs leading-5">
 98→          <tbody>
 99→            {lines.map((line, i) => (
100→              <tr key={i} className={lineStyles[line.type]}>
101→                {/* Old line number */}
102→                <td
103→                  className={`select-none text-right px-2 w-12 ${lineNumStyles[line.type]} border-r border-default/50`}
104→                >
105→                  {line.type === "hunk" || line.type === "header"
106→                    ? ""
107→                    : line.oldLineNum ?? ""}
108→                </td>
109→                {/* New line number */}
110→                <td
111→                  className={`select-none text-right px-2 w-12 ${lineNumStyles[line.type]} border-r border-default/50`}
112→                >
113→                  {line.type === "hunk" || line.type === "header"
114→                    ? ""
115→                    : line.newLineNum ?? ""}
116→                </td>
117→                {/* Prefix indicator */}
118→                <td className="select-none w-4 text-center">
119→                  {line.type === "add" && (
120→                    <span className="text-green-600 dark:text-green-400">+</span>
121→                  )}
122→                  {line.type === "remove" && (
123→                    <span className="text-red-600 dark:text-red-400">-</span>
124→                  )}
125→                </td>
126→                {/* Content */}
127→                <td className="whitespace-pre px-2">
128→                  {line.content || " "}
129→                </td>
130→              </tr>
131→            ))}
132→          </tbody>
133→        </table>
134→      </div>
135→
136→      {/* Truncation notice */}
137→      {truncated && (
138→        <div className="bg-amber-50 dark:bg-amber-900/20 border-t border-default px-3 py-2 text-amber-700 dark:text-amber-400 text-xs">
139→          Diff truncated due to size limits
140→        </div>
141→      )}
142→    </div>
143→  );
144→}
