132→// Detect GitHub 401 errors so we can tell the frontend to re-authenticate
133→// rather than showing a generic 500 error.
134→// GitHub lib throws errors in two formats:
135→//   "GitHub API error: 401" / "GitHub GraphQL error: 401"
136→//   "Failed to fetch <thing>: 401"
137→function isGitHubAuthError(err: unknown): boolean {
138→  if (!(err instanceof Error)) return false;
139→  return /: 401$/.test(err.message);
