181→  --background-color-primary: var(--surface-primary);
182→  --background-color-secondary: var(--surface-secondary);
183→  --background-color-muted: var(--surface-muted);
184→  --background-color-destructive: var(--destructive);
185→
186→  /* text-* utilities */
187→  --text-color-default: var(--text-default);
188→  --text-color-muted: var(--text-muted);
189→  --text-color-disabled: var(--text-disabled);
190→  --text-color-on-primary: var(--text-on-primary);
191→  --text-color-on-secondary: var(--text-on-secondary);
192→  --text-color-destructive: var(--destructive);
193→
194→  /* border-* utilities */
