196→  --border-color-subtle: var(--border-subtle);
197→  --border-color-destructive: var(--destructive);
198→  --border-color-ring: var(--ring);
199→
200→  /* ring-* utilities */
201→  --ring-color-default: var(--ring);
202→  --ring-color-border: var(--border-default);
203→  --ring-color-destructive: var(--destructive);
204→  --ring-color-focus: var(--focus);
205→
206→  /* divide-* utilities */
207→  --divide-color-default: var(--border-default);
208→
209→  /* outline-* utilities */
