211→  --outline-color-focus: var(--focus);
212→
213→  /* Trail status — text-status-*, bg-status-* */
214→  --text-color-status-draft: var(--status-draft);
215→  --text-color-status-open: var(--status-open);
216→  --text-color-status-in-progress: var(--status-in-progress);
