220→
221→  /* Generic color tokens (enables stroke-border, fill-border, etc.) */
222→  --color-border: var(--border-default);
223→  --color-muted: var(--text-muted);
224→  --color-status-draft: var(--status-draft);
225→  --color-status-open: var(--status-open);
226→  --color-status-in-progress: var(--status-in-progress);
227→  --color-status-in-review: var(--status-in-review);
228→  --color-status-merged: var(--status-merged);
229→  --color-status-closed: var(--status-closed);
