231→  /* Z-index layer scale — use isolation:isolate to contain these within layout boundaries */
232→  --z-index-sticky: 10;
233→  --z-index-panel: 30;
234→  --z-index-backdrop: 40;
235→  --z-index-overlay: 50;
236→  --z-index-modal: 60;
237→  --z-index-dialog: 61;
238→  --z-index-popover: 70; /* Popovers that appear above modals (e.g., combobox in dialog) */
239→}
