 16→// ============================================================================
 17→// Types
 18→// ============================================================================
 19→
 20→interface ListViewContextValue {
 21→  activeIndex: number;
 22→  setActiveIndex: (index: number) => void;
 23→  itemCount: number;
 24→  registerItem: (index: number, element: HTMLElement | null) => void;
 25→  onItemSelect: (index: number) => void;
 26→  onItemKeyDown: (e: KeyboardEvent, index: number) => void;
 27→  instanceId: string;
 28→}
 29→
 30→// ============================================================================
 31→// Context
 32→// ============================================================================
 33→
 34→const ListViewContext = createContext<ListViewContextValue | null>(null);
 35→
 36→function useListViewContext() {
 37→  const context = useContext(ListViewContext);
 38→  if (!context) {
 39→    throw new Error("ListView components must be used within a ListView");
 40→  }
 41→  return context;
 42→}
 43→
 44→// ============================================================================
 45→// ListView
 46→// ============================================================================
 47→
 48→interface ListViewProps {
 49→  children: ReactNode;
 50→  /** Total number of items in the list */
 51→  itemCount: number;
 52→  /** Called when an item is selected (Enter key or click) */
 53→  onSelect?: (index: number) => void;
 54→  /** Accessible label for the list */
 55→  "aria-label"?: string;
 56→  /** ID of element that labels this list */
 57→  "aria-labelledby"?: string;
 58→  className?: string;
 59→}
 60→
 61→/**
 62→ * An accessible list component with keyboard navigation.
 63→ *
 64→ * Uses roving tabindex pattern (WAI-ARIA best practice):
 65→ * - Only the active item is in the tab order (tabIndex="0")
 66→ * - Arrow Up/Down: Navigate between items
 67→ * - Home/End: Jump to first/last item
 68→ * - Enter/Space: Select the focused item
 69→ *
 70→ * @example
 71→ * ```tsx
 72→ * <ListView itemCount={items.length} onSelect={handleSelect} aria-label="Items">
 73→ *   {items.map((item, index) => (
 74→ *     <ListViewItem key={item.id} index={index}>
 75→ *       {item.name}
 76→ *     </ListViewItem>
 77→ *   ))}
 78→ * </ListView>
 79→ * ```
 80→ */
 81→export function ListView({
 82→  children,
 83→  itemCount,
 84→  onSelect,
 85→  "aria-label": ariaLabel,
 86→  "aria-labelledby": ariaLabelledby,
 87→  className,
 88→}: ListViewProps) {
 89→  const instanceId = useId();
 90→  const [rawActiveIndex, setRawActiveIndex] = useState(0);
 91→  const itemRefs = useRef<Map<number, HTMLElement>>(new Map());
 92→
 93→  // Ensure activeIndex is always within bounds
 94→  const activeIndex = useMemo(() => {
 95→    if (itemCount === 0) return 0;
 96→    return Math.min(Math.max(0, rawActiveIndex), itemCount - 1);
 97→  }, [rawActiveIndex, itemCount]);
 98→
 99→  const setActiveIndex = useCallback((index: number) => {
100→    setRawActiveIndex(index);
101→  }, []);
102→
103→  const registerItem = useCallback((index: number, element: HTMLElement | null) => {
104→    if (element) {
105→      itemRefs.current.set(index, element);
106→    } else {
107→      itemRefs.current.delete(index);
108→    }
109→  }, []);
110→
111→  const focusItem = useCallback((index: number) => {
112→    const element = itemRefs.current.get(index);
113→    element?.focus();
114→  }, []);
115→
116→  const onItemSelect = useCallback(
117→    (index: number) => {
118→      onSelect?.(index);
119→    },
120→    [onSelect]
121→  );
122→
123→  // Keyboard navigation handler (roving tabindex pattern)
124→  const onItemKeyDown = useCallback(
125→    (e: KeyboardEvent, currentIndex: number) => {
126→      if (itemCount === 0) return;
127→
128→      let newIndex = currentIndex;
129→      let handled = false;
130→
131→      switch (e.key) {
132→        case "ArrowDown":
133→          newIndex = currentIndex < itemCount - 1 ? currentIndex + 1 : 0;
134→          handled = true;
135→          break;
136→        case "ArrowUp":
137→          newIndex = currentIndex > 0 ? currentIndex - 1 : itemCount - 1;
138→          handled = true;
139→          break;
140→        case "Home":
141→          newIndex = 0;
142→          handled = true;
143→          break;
144→        case "End":
145→          newIndex = itemCount - 1;
146→          handled = true;
147→          break;
148→        case "Enter":
149→        case " ":
150→          onItemSelect(currentIndex);
151→          handled = true;
152→          break;
153→      }
154→
155→      if (handled) {
156→        e.preventDefault();
157→        if (newIndex !== currentIndex) {
158→          setActiveIndex(newIndex);
159→          focusItem(newIndex);
160→        }
161→      }
162→    },
163→    [itemCount, onItemSelect, focusItem, setActiveIndex]
164→  );
165→
166→  const contextValue = useMemo<ListViewContextValue>(
167→    () => ({
168→      activeIndex,
169→      setActiveIndex,
170→      itemCount,
171→      registerItem,
172→      onItemSelect,
173→      onItemKeyDown,
174→      instanceId,
175→    }),
176→    [activeIndex, setActiveIndex, itemCount, registerItem, onItemSelect, onItemKeyDown, instanceId]
177→  );
178→
179→  return (
180→    <ListViewContext.Provider value={contextValue}>
181→      <ul
182→        role="listbox"
183→        aria-label={ariaLabel}
184→        aria-labelledby={ariaLabelledby}
185→        className={twMerge("list-none p-0 m-0", className)}
186→      >
187→        {children}
188→      </ul>
189→    </ListViewContext.Provider>
190→  );
191→}
192→
193→// ============================================================================
194→// ListViewItem
195→// ============================================================================
196→
197→interface ListViewItemProps {
198→  /** Zero-based index of this item in the list */
199→  index: number;
200→  children: ReactNode;
201→  className?: string;
202→  /** Additional content announced to screen readers */
203→  "aria-label"?: string;
204→  /** URL for native "open in new tab" support (Cmd/Ctrl+Click) */
205→  href?: string;
206→}
207→
208→export function ListViewItem({
209→  index,
210→  children,
211→  className,
212→  "aria-label": ariaLabel,
213→  href,
214→}: ListViewItemProps) {
215→  const { activeIndex, setActiveIndex, registerItem, onItemSelect, onItemKeyDown, instanceId } =
216→    useListViewContext();
217→
218→  const itemRef = useRef<HTMLLIElement>(null);
219→  const isActive = activeIndex === index;
220→
221→  useEffect(() => {
222→    registerItem(index, itemRef.current);
223→    return () => registerItem(index, null);
224→  }, [index, registerItem]);
225→
226→  const handleClick = (e: MouseEvent<HTMLLIElement>) => {
227→    if (href && (e.metaKey || e.ctrlKey)) {
228→      window.open(href, "_blank");
229→    }
230→    setActiveIndex(index);
231→    onItemSelect(index);
232→  };
233→
234→  const handleKeyDown = (e: KeyboardEvent<HTMLLIElement>) => {
235→    onItemKeyDown(e, index);
236→  };
237→
238→  return (
239→    <li
240→      ref={itemRef}
241→      id={`listview-item-${instanceId}-${index}`}
242→      role="option"
243→      aria-selected={isActive}
244→      aria-label={ariaLabel}
245→      tabIndex={isActive ? 0 : -1}
246→      onClick={handleClick}
247→      onKeyDown={handleKeyDown}
248→      className={twMerge(
249→        "cursor-pointer",
250→        "focus:transition-none focus:outline-2 focus:-outline-offset-2 focus:outline-transparent focus-visible:outline-focus",
251→        className
252→      )}
253→    >
254→      {children}
255→    </li>
256→  );
257→}
