 86→async function embedTexts(
 87→  openaiApiKey: string,
 88→  texts: string[],
 89→): Promise<number[][]> {
 90→  const resp = await fetch("https://api.openai.com/v1/embeddings", {
 91→    method: "POST",
 92→    headers: {
 93→      Authorization: `Bearer ${openaiApiKey}`,
 94→      "Content-Type": "application/json",
 95→    },
 96→    body: JSON.stringify({
 97→      model: EMBEDDING_MODEL,
 98→      input: texts,
 99→      dimensions: EMBEDDING_DIMENSIONS,
100→    }),
101→  });
102→
103→  if (!resp.ok) {
104→    const err = await resp.text().catch(() => "");
105→    throw new Error(`OpenAI embedding failed (${resp.status}): ${err}`);
106→  }
107→
108→  const result = (await resp.json()) as {
109→    data: Array<{ index: number; embedding: number[] }>;
110→  };
111→  return result.data
112→    .sort((a, b) => a.index - b.index)
113→    .map((item) => item.embedding);
114→}
