317→export async function indexCheckpoints(
318→  turbopufferApiKey: string,
319→  openaiApiKey: string,
320→  githubId: number,
321→  checkpoints: Array<{
322→    checkpoint_id: string;
323→    branch: string | null;
324→    agent: string | null;
325→    commit_author_username: string | null;
326→    created_at: string | null;
327→    commit_sha: string | null;
328→    commit_message: string | null;
329→    prompt: string | null;
330→    files_touched: string[] | null;
331→    transcript?: string | null;
332→  }>,
333→): Promise<number> {
334→  // Build search text and filter out empty entries
335→  const validCheckpoints: Array<{
336→    checkpoint: (typeof checkpoints)[number];
337→    text: string;
338→  }> = [];
339→
340→  for (const cp of checkpoints) {
341→    const text = buildSearchText(cp);
342→    if (text.trim()) {
343→      validCheckpoints.push({ checkpoint: cp, text });
344→    }
345→  }
346→
347→  if (validCheckpoints.length === 0) {
348→    return 0;
349→  }
350→
351→  // Truncate texts for embedding model token limit
352→  const embeddingTexts = validCheckpoints.map((v) =>
353→    v.text.slice(0, MAX_EMBEDDING_CHARS),
354→  );
355→
356→  // Embed all texts in one batch call
357→  const embeddings = await embedTexts(openaiApiKey, embeddingTexts);
358→
359→  // Build upsert payload (row-based format for Turbopuffer v1 API)
360→  const upserts = validCheckpoints.map(({ checkpoint, text }, i) => {
361→    const filesTouchedStr = checkpoint.files_touched?.join(", ") ?? null;
362→    return {
363→      id: hashToNumericId(checkpoint.checkpoint_id),
364→      vector: embeddings[i],
365→      attributes: {
366→        checkpoint_id: checkpoint.checkpoint_id,
367→        branch: checkpoint.branch,
368→        agent: checkpoint.agent,
369→        author: checkpoint.commit_author_username,
370→        created_at: checkpoint.created_at,
371→        commit_sha: checkpoint.commit_sha,
372→        commit_message: truncateToBytes(
373→          checkpoint.commit_message,
374→          MAX_FILTERABLE_BYTES,
375→        ),
376→        prompt: truncateToBytes(checkpoint.prompt, MAX_FILTERABLE_BYTES),
377→        files_touched: truncateToBytes(filesTouchedStr, MAX_FILTERABLE_BYTES),
378→        text: truncateToBytes(text, MAX_TEXT_BYTES),
379→      },
380→    };
381→  });
382→
383→  // Upsert to Turbopuffer
384→  const namespace = `checkpoints-gh-${githubId}`;
385→  const url = `https://api.turbopuffer.com/v1/vectors/${encodeURIComponent(namespace)}`;
