import { request } from "@/lib/api";

export interface CommitInfo {
  sha: string;
  message: string;
  author: string;
  date: string;
  url: string;
}

export interface RepoCommitsResponse {
  commits: CommitInfo[];
  repo_full_name: string;
  updated_at: string;
  from_cache: boolean;
}

export async function fetchRepoCommits(
  org: string,
  repo: string,
): Promise<RepoCommitsResponse> {
  return request<RepoCommitsResponse>(`/api/v1/cache/${org}/${repo}/commits`);
}

export interface SessionInfo {
  prompt: string | null;
  agent: string;
  steps: number;
}

// Per-file stats for a commit
export interface FileStats {
  filename: string;
  status: "added" | "removed" | "modified" | "renamed" | "copied" | "changed" | "unchanged";
  additions: number;
  deletions: number;
  patch?: string | null;      // Unified diff for this file
  patchTruncated?: boolean;   // True if patch was truncated due to size limits
}

export interface CheckpointInfo {
  commitSha: string;
  commitMessage: string;
  commitAuthor: string;
  commitAuthorUsername: string;
  commitDate: string;
  additions: number;
  deletions: number;
  // Per-file stats with additions/deletions breakdown
  fileStats: FileStats[] | null;
  checkpointId: string;
  sessions: SessionInfo[];
  sessionCount: number;
  totalSteps: number;
  agents: string[];
  // Token usage (may be null if not tracked)
  inputTokens: number | null;
  outputTokens: number | null;
  // Attribution data (may be null if not calculated)
  attribution: SessionAttribution | null;
}

export interface CheckpointsResponse {
  checkpoints: CheckpointInfo[];
  repo_full_name: string;
  updated_at: string;
  from_cache: boolean;
  app_has_access: boolean | null; // null = unknown (API error)
  session_branch_exists: boolean | null; // null = unknown (API error)
}

export async function fetchCheckpoints(
  org: string,
  repo: string,
  branch: string = "main",
  options?: { source?: "github" }
): Promise<CheckpointsResponse> {
  const params = new URLSearchParams({ branch });
  if (options?.source) {
    params.set("source", options.source);
  }
  return request<CheckpointsResponse>(
    `/api/v1/cache/${org}/${repo}/checkpoints?${params.toString()}`
  );
}

export interface CheckpointStatusResponse {
  app_has_access: boolean | null;
  session_branch_exists: boolean | null;
  checkpoint_count: number;
}

export async function fetchCheckpointStatus(
  org: string,
  repo: string,
): Promise<CheckpointStatusResponse> {
  return request<CheckpointStatusResponse>(
    `/api/v1/cache/${org}/${repo}/checkpoint-status`
  );
}

export interface BranchesResponse {
  branches: string[];
  default_branch: string;
  stored_default_branch: string;
  from_cache: boolean;
}

export async function fetchBranches(
  org: string,
  repo: string,
): Promise<BranchesResponse> {
  return request<BranchesResponse>(`/api/v1/cache/${org}/${repo}/branches`);
}

// Transcript types
export interface TranscriptImage {
  mediaType: string;
  data: string; // base64 encoded
}

// Tool call result metadata
export interface ToolCallResult {
  type: "text" | "error";
  file?: {
    filePath: string;
    numLines?: number;
  };
  matchCount?: number;
  output?: string;
  error?: string;
  // For AskUserQuestion tool calls - the user's answers
  answers?: Record<string, string>;
}

// Raw tool_use block
export interface ToolUseBlock {
  id: string;
  name: string;
  input: Record<string, unknown>;
}

// Tool call made by the agent during a turn
export interface ToolCall extends ToolUseBlock {
  timestamp: string;
  result?: ToolCallResult;
}

export interface TranscriptMessage {
  id: string;
  role: "user" | "assistant";
  content: string;
  images?: TranscriptImage[];
  timestamp: string;
  toolCalls?: ToolCall[];
}

// Per-session line-level attribution
export interface SessionAttribution {
  calculatedAt: string;
  agentLines: number;
  humanAdded: number;
  humanModified: number;
  humanRemoved: number;
  totalCommitted: number;
  agentPercentage: number;
}

export interface SessionTranscript {
  sessionId: string;
  agent: string;
  messages: TranscriptMessage[];
  // Transcript state at session start - used to show only relevant messages
  transcriptIdentifierAtStart: string | null;
  // Per-session token usage (from child metadata.json)
  tokenUsage?: {
    inputTokens: number;
    outputTokens: number;
  };
  // Per-session line-level attribution (from child metadata.json)
  attribution?: SessionAttribution;
  // Parse quality indicators
  /** True when a native parser was not available for this agent */
  parsingFallback?: boolean;
  /** Warning message when transcript parsing may be incomplete */
  parsingWarning?: string;
}

export interface CheckpointTranscriptResponse {
  checkpointId: string;
  sessions: SessionTranscript[];
}

export async function fetchCheckpointTranscript(
  org: string,
  repo: string,
  checkpointId: string,
): Promise<CheckpointTranscriptResponse> {
  return request<CheckpointTranscriptResponse>(
    `/api/v1/cache/${org}/${repo}/checkpoints/${encodeURIComponent(checkpointId)}/transcript`
  );
}

// Resolve checkpoint location - finds which branches a checkpoint exists on
// Used when the original branch has been deleted (e.g., after PR merge)
export interface CheckpointResolveResponse {
  checkpoint_id: string;
  branches: string[];
  default_branch: string | null;
  suggested_branch: string;
  needs_redirect: boolean;
  requested_branch: string | null;
  checkpoint: CheckpointInfo | null;
  repo_full_name: string;
}

export async function resolveCheckpoint(
  org: string,
  repo: string,
  checkpointId: string,
  requestedBranch?: string,
): Promise<CheckpointResolveResponse> {
  const params = requestedBranch
    ? `?branch=${encodeURIComponent(requestedBranch)}`
    : "";
  return request<CheckpointResolveResponse>(
    `/api/v1/cache/${org}/${repo}/checkpoints/resolve/${encodeURIComponent(checkpointId)}${params}`
  );
}

export async function searchCheckpoints(
  org: string,
  repo: string,
  query: string,
  branch?: string,
): Promise<CheckpointsResponse> {
  const params = new URLSearchParams({ q: query });
  if (branch) params.set("branch", branch);
  return request<CheckpointsResponse>(
    `/api/v1/cache/${org}/${repo}/checkpoints/search?${params.toString()}`
  );
}

