  1→// Turbopuffer vector search client for checkpoints
  2→// Uses hybrid search: OpenAI embeddings (cosine similarity) + BM25 full-text search,
  3→// combined via Reciprocal Rank Fusion (RRF) for best results on both
  4→// semantic and exact keyword queries.
  5→
  6→const EMBEDDING_MODEL = "text-embedding-3-small";
  7→const EMBEDDING_DIMENSIONS = 1536;
  8→const MAX_EMBEDDING_CHARS = 25000; // ~8K tokens, text-embedding-3-small limit is 8192 tokens
  9→const MAX_FILTERABLE_BYTES = 3800; // Turbopuffer 4 KiB limit on filterable attributes
 10→const MAX_TEXT_BYTES = 500_000; // text field is non-filterable (8 MiB limit), generous cap for BM25
 11→
 12→export interface TurbopufferSearchResult {
 13→  checkpoint_id: string;
 14→}
 15→
 16→// v1 API response: bare array with nested attributes
 17→interface TurbopufferV1Row {
 18→  id: number;
 19→  dist: number;
 20→  attributes: {
 21→    checkpoint_id?: string;
 22→  };
 23→}
 24→
 25→// v2 API response: { rows: [...] } with flat attributes
 26→interface TurbopufferV2Row {
 27→  id: number;
 28→  $dist: number;
 29→  checkpoint_id?: string;
 30→}
 31→
 32→interface TurbopufferV2Response {
 33→  rows: TurbopufferV2Row[];
 34→}
 35→
 36→// Normalized row used internally
 37→export interface SearchRow {
 38→  checkpoint_id: string | undefined;
 39→  dist: number;
 40→}
 41→
 42→export function truncateToBytes(str: string | null, maxBytes: number): string | null {
 43→  if (str === null) return null;
 44→  if (str.length <= maxBytes) return str;
 45→  const encoder = new TextEncoder();
 46→  const encoded = encoder.encode(str);
 47→  if (encoded.length <= maxBytes) return str;
 48→  const truncated = encoded.slice(0, maxBytes);
 49→  const decoder = new TextDecoder();
 50→  return decoder.decode(truncated);
 51→}
 52→
 53→export function buildSearchText(checkpoint: {
 54→  prompt: string | null;
 55→  commit_message: string | null;
 56→  files_touched: string[] | null;
 57→  transcript?: string | null;
 58→}): string {
 59→  const parts: string[] = [];
 60→  if (checkpoint.prompt) {
 61→    parts.push(`Prompt: ${checkpoint.prompt}`);
 62→  }
 63→  if (checkpoint.commit_message) {
 64→    parts.push(`Commit: ${checkpoint.commit_message}`);
 65→  }
 66→  if (checkpoint.files_touched) {
 67→    parts.push(`Files: ${checkpoint.files_touched.join(", ")}`);
 68→  }
 69→  if (checkpoint.transcript) {
 70→    parts.push(`Transcript: ${checkpoint.transcript}`);
 71→  }
 72→  return parts.join("\n");
 73→}
 74→
 75→// Hash checkpoint_id to a deterministic numeric ID for Turbopuffer
 76→// Uses FNV-1a 32-bit hash for fast, well-distributed IDs
 77→export function hashToNumericId(checkpointId: string): number {
 78→  let hash = 0x811c9dc5; // FNV offset basis
 79→  for (let i = 0; i < checkpointId.length; i++) {
 80→    hash ^= checkpointId.charCodeAt(i);
 81→    hash = Math.imul(hash, 0x01000193); // FNV prime
 82→  }
 83→  return hash >>> 0; // unsigned 32-bit
 84→}
 85→
 86→async function embedTexts(
 87→  openaiApiKey: string,
 88→  texts: string[],
 89→): Promise<number[][]> {
 90→  const resp = await fetch("https://api.openai.com/v1/embeddings", {
 91→    method: "POST",
 92→    headers: {
 93→      Authorization: `Bearer ${openaiApiKey}`,
 94→      "Content-Type": "application/json",
 95→    },
 96→    body: JSON.stringify({
 97→      model: EMBEDDING_MODEL,
 98→      input: texts,
 99→      dimensions: EMBEDDING_DIMENSIONS,
100→    }),
101→  });
102→
103→  if (!resp.ok) {
104→    const err = await resp.text().catch(() => "");
105→    throw new Error(`OpenAI embedding failed (${resp.status}): ${err}`);
106→  }
107→
108→  const result = (await resp.json()) as {
109→    data: Array<{ index: number; embedding: number[] }>;
110→  };
111→  return result.data
112→    .sort((a, b) => a.index - b.index)
113→    .map((item) => item.embedding);
114→}
115→
116→async function embedQuery(openaiApiKey: string, text: string): Promise<number[]> {
117→  const resp = await fetch("https://api.openai.com/v1/embeddings", {
118→    method: "POST",
119→    headers: {
120→      Authorization: `Bearer ${openaiApiKey}`,
121→      "Content-Type": "application/json",
122→    },
123→    body: JSON.stringify({
124→      model: EMBEDDING_MODEL,
125→      input: text,
126→      dimensions: EMBEDDING_DIMENSIONS,
127→    }),
128→  });
129→
130→  if (!resp.ok) {
131→    const err = await resp.text().catch(() => "");
132→    throw new Error(`OpenAI embedding failed (${resp.status}): ${err}`);
133→  }
134→
135→  const result = (await resp.json()) as { data: Array<{ embedding: number[] }> };
136→  return result.data[0].embedding;
137→}
138→
139→// RRF constant — standard value that prevents top-ranked items from dominating
140→export const RRF_K = 60;
141→
142→export interface RRFResult {
143→  checkpoint_id: string;
144→  rrf: number;
145→  vectorRank: number | null;
146→  bm25Rank: number | null;
147→}
148→
149→// Merge two ranked lists via Reciprocal Rank Fusion
150→// score(doc) = 1/(k + rank_vector) + 1/(k + rank_bm25)
151→export function mergeRRF(
152→  vectorResults: SearchRow[],
153→  bm25Results: SearchRow[],
154→  limit: number,
155→): RRFResult[] {
156→  const scores = new Map<string, { rrf: number; vectorRank: number | null; bm25Rank: number | null }>();
157→
158→  for (let rank = 0; rank < vectorResults.length; rank++) {
159→    const id = vectorResults[rank].checkpoint_id;
160→    if (id) {
161→      const entry = scores.get(id) ?? { rrf: 0, vectorRank: null, bm25Rank: null };
162→      entry.rrf += 1 / (RRF_K + rank + 1);
163→      entry.vectorRank = rank + 1;
164→      scores.set(id, entry);
165→    }
166→  }
167→
168→  for (let rank = 0; rank < bm25Results.length; rank++) {
169→    const id = bm25Results[rank].checkpoint_id;
170→    if (id) {
171→      const entry = scores.get(id) ?? { rrf: 0, vectorRank: null, bm25Rank: null };
172→      entry.rrf += 1 / (RRF_K + rank + 1);
173→      entry.bm25Rank = rank + 1;
174→      scores.set(id, entry);
175→    }
176→  }
177→
178→  return [...scores.entries()]
179→    .sort((a, b) => b[1].rrf - a[1].rrf)
180→    .slice(0, limit)
181→    .map(([checkpoint_id, s]) => ({ checkpoint_id, ...s }));
182→}
183→
184→export async function searchCheckpoints(
185→  turbopufferApiKey: string,
186→  openaiApiKey: string,
187→  githubId: number,
188→  query: string,
189→  filters?: { branch?: string },
190→  limit: number = 50,
191→): Promise<TurbopufferSearchResult[]> {
192→  const namespace = `checkpoints-gh-${githubId}`;
193→
194→  const headers = {
195→    Authorization: `Bearer ${turbopufferApiKey}`,
196→    "Content-Type": "application/json",
197→  };
198→
199→  const branchFilters = filters?.branch
200→    ? { branch: [["Eq", filters.branch]] }
201→    : undefined;
202→
203→  // Fire vector + BM25 queries in parallel, gracefully degrade if either fails
204→  const [vectorResult, bm25Result] = await Promise.all([
205→    // Vector cosine similarity (v1 API)
206→    (async (): Promise<{ rows: SearchRow[]; error?: string }> => {
207→      try {
208→        const vector = await embedQuery(openaiApiKey, query);
209→        const url = `https://api.turbopuffer.com/v1/vectors/${encodeURIComponent(namespace)}/query`;
210→        const body: Record<string, unknown> = {
211→          vector,
212→          top_k: limit,
213→          distance_metric: "cosine_distance",
214→          include_attributes: ["checkpoint_id"],
215→        };
216→        if (branchFilters) body.filters = branchFilters;
217→
218→        const resp = await fetch(url, {
219→          method: "POST",
220→          headers,
221→          body: JSON.stringify(body),
222→        });
223→        if (!resp.ok) {
224→          const text = await resp.text().catch(() => "");
225→          return { rows: [], error: `vector query failed (${resp.status}): ${text}` };
226→        }
227→        const rows = (await resp.json()) as TurbopufferV1Row[];
228→        return { rows: rows.map((r) => ({ checkpoint_id: r.attributes?.checkpoint_id, dist: r.dist })) };
229→      } catch (err) {
230→        return { rows: [], error: `vector query error: ${err instanceof Error ? err.message : String(err)}` };
231→      }
232→    })(),
233→
234→    // BM25 full-text search (v2 API)
235→    (async (): Promise<{ rows: SearchRow[]; error?: string }> => {
236→      try {
237→        const url = `https://api.turbopuffer.com/v2/namespaces/${encodeURIComponent(namespace)}/query`;
238→        const body: Record<string, unknown> = {
239→          rank_by: ["text", "BM25", query],
240→          top_k: limit,
241→          include_attributes: ["checkpoint_id"],
242→        };
243→        if (branchFilters) body.filters = branchFilters;
244→
245→        const resp = await fetch(url, {
246→          method: "POST",
247→          headers,
248→          body: JSON.stringify(body),
249→        });
250→        if (!resp.ok) {
251→          const text = await resp.text().catch(() => "");
252→          return { rows: [], error: `BM25 query failed (${resp.status}): ${text}` };
253→        }
254→        const data = (await resp.json()) as TurbopufferV2Response;
255→        return { rows: data.rows.map((r) => ({ checkpoint_id: r.checkpoint_id, dist: r.$dist })) };
256→      } catch (err) {
257→        return { rows: [], error: `BM25 query error: ${err instanceof Error ? err.message : String(err)}` };
258→      }
259→    })(),
260→  ]);
261→
262→  const vectorResults = vectorResult.rows;
263→  const bm25Results = bm25Result.rows;
264→
265→  if (vectorResult.error) console.warn(`[search] ${vectorResult.error}`);
266→  if (bm25Result.error) console.warn(`[search] ${bm25Result.error}`);
267→
268→  // If both failed, return empty so client falls back to local filtering
269→  if (vectorResults.length === 0 && bm25Results.length === 0) {
270→    console.warn(`[search] both sources returned no results`);
271→    return [];
272→  }
273→
274→  console.log(`[search] query="${query}" namespace=${namespace}`);
275→  console.log(`[search] vector results: ${vectorResults.length}, bm25 results: ${bm25Results.length}`);
276→
277→  // Log top results from each source with their raw scores
278→  const topN = 5;
279→  if (vectorResults.length > 0) {
280→    console.log(`[search] top ${topN} vector (cosine dist):`,
281→      vectorResults.slice(0, topN).map((r, i) => ({
282→        rank: i + 1,
283→        checkpoint_id: r.checkpoint_id?.slice(0, 8),
284→        dist: r.dist?.toFixed(4),
285→      })),
286→    );
287→  }
288→  if (bm25Results.length > 0) {
289→    console.log(`[search] top ${topN} bm25:`,
290→      bm25Results.slice(0, topN).map((r, i) => ({
291→        rank: i + 1,
292→        checkpoint_id: r.checkpoint_id?.slice(0, 8),
293→        dist: r.dist?.toFixed(4),
294→      })),
295→    );
296→  }
297→
298→  const merged = mergeRRF(vectorResults, bm25Results, limit);
299→
300→  // Log final merged results
301→  console.log(`[search] top ${topN} RRF merged:`,
302→    merged.slice(0, topN).map((r) => ({
303→      checkpoint_id: r.checkpoint_id.slice(0, 8),
304→      rrf: r.rrf.toFixed(6),
305→      vectorRank: r.vectorRank,
306→      bm25Rank: r.bm25Rank,
307→      source: r.vectorRank && r.bm25Rank ? "both" : r.vectorRank ? "vector-only" : "bm25-only",
308→    })),
309→  );
310→
311→  return merged.map((r) => ({ checkpoint_id: r.checkpoint_id }));
312→}
313→
314→// Index checkpoints into Turbopuffer for vector search
315→// Builds search text, embeds via OpenAI, and upserts to Turbopuffer
316→// Returns the number of successfully indexed checkpoints
317→export async function indexCheckpoints(
318→  turbopufferApiKey: string,
319→  openaiApiKey: string,
320→  githubId: number,
321→  checkpoints: Array<{
322→    checkpoint_id: string;
323→    branch: string | null;
324→    agent: string | null;
325→    commit_author_username: string | null;
326→    created_at: string | null;
327→    commit_sha: string | null;
328→    commit_message: string | null;
329→    prompt: string | null;
330→    files_touched: string[] | null;
331→    transcript?: string | null;
332→  }>,
333→): Promise<number> {
334→  // Build search text and filter out empty entries
335→  const validCheckpoints: Array<{
336→    checkpoint: (typeof checkpoints)[number];
337→    text: string;
338→  }> = [];
339→
340→  for (const cp of checkpoints) {
341→    const text = buildSearchText(cp);
342→    if (text.trim()) {
343→      validCheckpoints.push({ checkpoint: cp, text });
344→    }
345→  }
346→
347→  if (validCheckpoints.length === 0) {
348→    return 0;
349→  }
350→
351→  // Truncate texts for embedding model token limit
352→  const embeddingTexts = validCheckpoints.map((v) =>
353→    v.text.slice(0, MAX_EMBEDDING_CHARS),
354→  );
355→
